package com.ironspubbingo;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Starts a RuneLite dev client with this plugin loaded ({@code gradlew run}).
 * Lives in its own source set so the plugin builds without any dev or test code.
 */
public class IronsPubBingoDevLauncher
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(IronsPubBingoPlugin.class);
		RuneLite.main(args);
	}
}

package com.ironspubbingo;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.time.Instant;
import java.time.LocalDate;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.time.format.DateTimeParseException;
import java.util.List;
import java.util.Locale;

/**
 * A bingo board, deserialized from the shareable board JSON.
 */
public class BingoBoard
{
	String name;
	/**
	 * Optional stable identifier. Boards sharing an id share progress and team sync, so a
	 * host can edit the board mid-event without resetting anyone. Labels, icons, points,
	 * targets and even what a tile tracks can all change, as long as tiles keep their
	 * position (edit in place, don't insert or reorder). Only a new id (or removing it) is a new board.
	 */
	String id;
	/** Optional board revision, shown next to the board name. */
	Integer version;
	/** Optional event start (ISO 8601, e.g. "2026-08-29T18:00Z"). Tracking only counts after it. */
	String start;
	/** Optional event end. Tracking stops counting once passed. */
	String end;
	/** Optional bonus points per completed bingo line (row, column or diagonal). */
	Integer linePoints;
	/** Whether the two diagonals count as bingo lines. Default true. */
	Boolean diagonals;
	/** Optional bonus points for completing the whole board. */
	Integer blackoutPoints;
	int size;
	List<BingoTile> tiles;

	transient String normalizedId;
	transient Instant startTime;
	transient Instant endTime;

	/**
	 * Parses and validates a board.
	 *
	 * @return the parsed board
	 * @throws IllegalArgumentException with a user-facing message when invalid
	 */
	static BingoBoard parse(Gson gson, String json)
	{
		BingoBoard board;
		try
		{
			board = gson.fromJson(json, BingoBoard.class);
		}
		catch (JsonSyntaxException e)
		{
			throw new IllegalArgumentException("Not valid JSON: " + e.getMessage());
		}
		if (board == null)
		{
			throw new IllegalArgumentException("Board is empty");
		}
		String err = board.validate();
		if (err != null)
		{
			throw new IllegalArgumentException(err);
		}
		return board;
	}

	private String validate()
	{
		if (name == null || name.trim().isEmpty())
		{
			name = "Irons Pub Bingo";
		}
		if (id != null && !id.trim().isEmpty())
		{
			String normalized = id.trim().toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9-_]", "");
			if (normalized.isEmpty())
			{
				return "Board id must contain letters, numbers, '-' or '_'";
			}
			if (normalized.length() > 40)
			{
				return "Board id is too long (max 40 characters)";
			}
			normalizedId = normalized;
		}
		if (version != null && version < 0)
		{
			return "'version' must not be negative";
		}
		if (start != null && !start.trim().isEmpty())
		{
			try
			{
				startTime = parseTime(start);
			}
			catch (DateTimeParseException e)
			{
				return "Could not read 'start' (" + start + "). Use a date like 2026-08-29T18:00Z";
			}
		}
		if (end != null && !end.trim().isEmpty())
		{
			try
			{
				endTime = parseTime(end);
			}
			catch (DateTimeParseException e)
			{
				return "Could not read 'end' (" + end + "). Use a date like 2026-09-07T20:00Z";
			}
		}
		if (startTime != null && endTime != null && !endTime.isAfter(startTime))
		{
			return "'end' must be after 'start'";
		}
		if (linePoints != null && linePoints < 0)
		{
			return "'linePoints' must not be negative";
		}
		if (blackoutPoints != null && blackoutPoints < 0)
		{
			return "'blackoutPoints' must not be negative";
		}
		if (size < 1 || size > 10)
		{
			return "Board size must be between 1 and 10 (got " + size + ")";
		}
		if (tiles == null || tiles.size() != size * size)
		{
			return "A " + size + "x" + size + " board needs exactly " + (size * size)
				+ " tiles (got " + (tiles == null ? 0 : tiles.size()) + ")";
		}
		for (int i = 0; i < tiles.size(); i++)
		{
			BingoTile tile = tiles.get(i);
			if (tile == null)
			{
				return "tile " + (i + 1) + ": empty tile";
			}
			String err = tile.validate(i);
			if (err != null)
			{
				return err;
			}
		}
		return null;
	}

	/**
	 * Accepts ISO 8601 instants leniently: "2026-08-29" (midnight UTC), "2026-08-29T18:00Z"
	 * (seconds optional, UTC assumed when no zone given) and explicit offsets.
	 */
	static Instant parseTime(String raw)
	{
		String v = raw.trim();
		if (v.matches("\\d{4}-\\d{2}-\\d{2}"))
		{
			return LocalDate.parse(v).atStartOfDay(ZoneOffset.UTC).toInstant();
		}
		if (v.matches(".*T\\d{2}:\\d{2}"))
		{
			v += ":00";
		}
		else if (v.matches(".*T\\d{2}:\\d{2}Z"))
		{
			v = v.substring(0, v.length() - 1) + ":00Z";
		}
		if (!v.endsWith("Z") && !v.matches(".*[+-]\\d{2}:?\\d{2}$"))
		{
			v += "Z";
		}
		try
		{
			return Instant.parse(v);
		}
		catch (DateTimeParseException e)
		{
			return OffsetDateTime.parse(v).toInstant();
		}
	}

	/**
	 * The key progress and team sync are stored under. Without an id, any edit at all is a
	 * new board. With one, the id IS the board: hosts may tune tiles mid-event without a
	 * reset. Tampering is not this key's job - the store rejects any client whose exact
	 * board code differs from the host's, and that gate is what keeps store events honest.
	 */
	String storageKey(Gson gson)
	{
		if (normalizedId == null)
		{
			return Integer.toHexString(gson.toJson(this).hashCode());
		}
		return identityKey();
	}

	/** The board's identity across revisions (its host-set id), or null when it has none. */
	String identityKey()
	{
		return normalizedId == null ? null : "id_" + normalizedId;
	}

	int linePointsValue()
	{
		return linePoints == null || linePoints < 0 ? 0 : linePoints;
	}

	int blackoutPointsValue()
	{
		return blackoutPoints == null || blackoutPoints < 0 ? 0 : blackoutPoints;
	}

	/** Rows + columns, plus both diagonals when they count. */
	int maxLines()
	{
		return 2 * size + (diagonalsCount() ? 2 : 0);
	}

	boolean diagonalsCount()
	{
		return diagonals == null || diagonals;
	}

	String getName()
	{
		return name;
	}

	int getSize()
	{
		return size;
	}

	List<BingoTile> getTiles()
	{
		return tiles;
	}
}

package com.ironspubbingo;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import java.awt.event.ComponentAdapter;
import java.awt.event.ComponentEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.JFrame;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;

/**
 * Resizable pop-out window with a large view of the bingo board: icons, full tile labels,
 * points and progress colors. Opened from the sidebar panel; clicking a tile selects it
 * there. Live-updates together with the panel.
 */
class BingoBoardWindow extends JFrame
{
	private final IronsPubBingoPlugin plugin;
	private final JLabel titleLabel = new JLabel();
	private final JLabel subLabel = new JLabel();
	private final BingoUi.Chip tilesChip = new BingoUi.Chip();
	private final BingoUi.Chip linesChip = new BingoUi.Chip();
	private final BingoUi.Chip pointsChip = new BingoUi.Chip();
	private final BingoUi.Chip rankChip = new BingoUi.Chip();
	private final BingoUi.Chip eventChip = new BingoUi.Chip();
	private final BingoGridPanel grid = new BingoGridPanel();
	private static final int DETAIL_WIDTH = 380;
	private static final String SELECT_TILE_HINT = "<html><div style='text-align:center'>Select a tile to see its goals,<br>"
		+ "who contributed and its actions.</div></html>";
	private static final String NO_BOARD_HINT = "<html><div style='text-align:center'>No board loaded.</div></html>";
	private final BingoTileDetail detail;
	private final JScrollPane detailScroll;
	private final JPanel detailCards = new JPanel(new java.awt.CardLayout());
	private final JLabel detailHint = new JLabel();
	private final javax.swing.JButton detailsToggle = new javax.swing.JButton();
	private boolean detailsShown;
	/** Below this body width the detail moves under the board instead of beside it. */
	private static final int SIDE_BY_SIDE_MIN_WIDTH = 720;
	private final List<BingoTileCell> cells = new ArrayList<>();
	private final List<JLabel> cellIcons = new ArrayList<>();
	private final List<BingoWrappedLabel> cellLabels = new ArrayList<>();
	private BingoBoard renderedBoard;
	/** Whether the grid was built at all. renderedBoard alone can't tell: it starts null. */
	private boolean gridBuilt;
	private final javax.swing.Timer countdownTimer;

	BingoBoardWindow(IronsPubBingoPlugin plugin)
	{
		this.plugin = plugin;
		setTitle("Irons Pub Bingo");
		setIconImage(ImageUtil.loadImageResource(IronsPubBingoPlugin.class, "window_icon.png"));
		setDefaultCloseOperation(HIDE_ON_CLOSE);
		setSize(1060, 720);
		setMinimumSize(new Dimension(440, 560));

		JPanel content = new JPanel(new BorderLayout(0, 8));
		content.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		content.add(buildHeader(), BorderLayout.NORTH);

		grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
		grid.addComponentListener(new ComponentAdapter()
		{
			@Override
			public void componentResized(ComponentEvent e)
			{
				refresh(); // re-wrap tile labels to the new cell width
			}
		});
		// The same tile detail as the sidebar, for the selected tile. It keeps the sidebar's
		// fixed content width - all its wrap widths and bar labels are computed for that
		// basis, and stretching it breaks them. So it gets a fixed-width column beside the
		// board, which takes all the rest; in a narrow window it moves under the board.
		detail = new BingoTileDetail(plugin, DETAIL_WIDTH);
		JPanel detailHolder = new JPanel(new java.awt.GridBagLayout());
		detailHolder.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		detailHolder.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		java.awt.GridBagConstraints holderConstraints = new java.awt.GridBagConstraints();
		holderConstraints.anchor = java.awt.GridBagConstraints.NORTH;
		holderConstraints.weightx = 1;
		holderConstraints.weighty = 1;
		detailHolder.add(detail, holderConstraints);
		detailScroll = new JScrollPane(detailHolder,
			JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		detailScroll.setBorder(BorderFactory.createEmptyBorder());
		detailScroll.getViewport().setBackground(ColorScheme.DARKER_GRAY_COLOR);
		detailScroll.getVerticalScrollBar().setUnitIncrement(16);

		detailHint.setHorizontalAlignment(SwingConstants.CENTER);
		detailHint.setFont(FontManager.getRunescapeSmallFont());
		detailHint.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		JPanel hintPanel = new JPanel(new BorderLayout());
		hintPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		hintPanel.add(detailHint, BorderLayout.CENTER);

		detailCards.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		detailCards.setBorder(BorderFactory.createLineBorder(BingoUi.COLOR_CHIP_EDGE));
		detailCards.add(detailScroll, "detail");
		detailCards.add(hintPanel, "hint");

		JPanel body = new JPanel(new BodyLayout());
		body.setOpaque(false);
		body.add(grid);
		body.add(detailCards);
		detailCards.setVisible(detailsShown);
		content.add(body, BorderLayout.CENTER);
		setContentPane(content);

		// Keeps the "Time left" countdown in the status line ticking while visible.
		countdownTimer = new javax.swing.Timer(1000, e ->
		{
			if (isVisible())
			{
				updateStatusLine();
			}
		});
		countdownTimer.start();
	}

	@Override
	public void dispose()
	{
		countdownTimer.stop();
		super.dispose();
	}

	void open()
	{
		setAlwaysOnTop(plugin.popOutAlwaysOnTop());
		refresh();
		setVisible(true);
		toFront();
	}

	void refresh()
	{
		BingoBoard board = plugin.getBoard();
		if (!gridBuilt || board != renderedBoard)
		{
			rebuildGrid(board);
			renderedBoard = board;
			gridBuilt = true;
		}
		setText(detailHint, board == null ? NO_BOARD_HINT : SELECT_TILE_HINT);
		if (board == null)
		{
			setTitle("Irons Pub Bingo");
			titleLabel.setText("No board loaded");
			subLabel.setText("Import a board in the side panel to see it here.");
			setChipsVisible(false);
			showDetail(false);
			return;
		}

		detail.setSelectedTile(plugin.selectedTileIndex());
		showDetail(detail.rebuild());
		detail.revalidate();
		detail.repaint();

		setTitle("Irons Pub Bingo - " + board.getName());
		updateStatusLine();

		int size = board.getSize();
		// Actual cell width: grid width minus the inter-cell gaps, minus padding.
		int gridWidth = grid.getWidth() > 0 ? grid.getWidth() : 640;
		int textWidth = Math.max(48, (gridWidth - (size - 1) * 4) / size - 16);
		boolean drawLines = plugin.lineDisplay() == LineDisplay.LINES;
		boolean fillMode = plugin.progressFill();
		int selected = plugin.selectedTileIndex();
		grid.setLines(size, drawLines ? plugin.completedLineSegments() : java.util.Collections.emptyList(), plugin.lineColor());
		java.util.Set<Integer> lineCells = drawLines ? java.util.Collections.emptySet() : plugin.completedLineCells();
		for (int i = 0; i < cells.size(); i++)
		{
			BingoTile tile = board.getTiles().get(i);
			BingoTileCell cell = cells.get(i);
			boolean complete = plugin.isTileComplete(i);
			// Amber for any progress in the classic look; in fill mode the amber rises from the bottom.
			boolean partial = !complete && !fillMode && plugin.tileHasProgress(i);
			cell.setState(complete, partial, complete || !fillMode ? 0f : (float) plugin.tileProgressFraction(i),
				i == selected, lineCells.contains(i), plugin.lineColor());
			cellLabels.get(i).setWrapWidth(textWidth);
			String tooltip = "<html><b>" + BingoUi.escapeHtml(tile.label) + "</b><br>"
				+ (complete ? "Complete" : plugin.tileGoalSummaryHtml(i)) + "</html>";
			cell.setToolTipText(tooltip);
			cellIcons.get(i).setToolTipText(tooltip);
			cellLabels.get(i).setToolTipText(tooltip);
		}
		revalidate();
		repaint();
	}

	private void setDetailsShown(boolean shown)
	{
		detailsShown = shown;
		plugin.setPopOutDetailsShown(shown);
		updateDetailsToggle();
		detailCards.setVisible(shown);
		detailCards.getParent().revalidate();
		detailCards.getParent().repaint();
	}

	private void updateDetailsToggle()
	{
		detailsToggle.setText(detailsShown ? "Hide details" : "Show details");
		detailsToggle.setToolTipText(detailsShown ? "Give the whole window to the board"
			: "Show the selected tile's goals, contributors and actions");
	}

	private void showDetail(boolean tileSelected)
	{
		((java.awt.CardLayout) detailCards.getLayout()).show(detailCards, tileSelected ? "detail" : "hint");
	}

	/**
	 * Lays out the board (kept square, centered) and the detail column. Wide: the detail is
	 * a fixed-width column on the right. Narrow: it sits under the board with a share of
	 * the height, so the window can be resized freely and the detail never disappears.
	 */
	private final class BodyLayout implements java.awt.LayoutManager
	{
		private static final int GAP = 10;

		@Override
		public void layoutContainer(java.awt.Container parent)
		{
			int w = parent.getWidth();
			int h = parent.getHeight();
			int detailWidth = DETAIL_WIDTH + 22 + detailScroll.getVerticalScrollBar().getPreferredSize().width;
			java.awt.Rectangle boardArea;
			if (!detailsShown)
			{
				boardArea = new java.awt.Rectangle(0, 0, w, h);
			}
			else if (w >= SIDE_BY_SIDE_MIN_WIDTH)
			{
				detailCards.setBounds(w - detailWidth, 0, detailWidth, h);
				boardArea = new java.awt.Rectangle(0, 0, w - detailWidth - GAP, h);
			}
			else
			{
				int detailHeight = Math.max(200, Math.round(h * 0.42f));
				detailCards.setBounds(0, h - detailHeight, w, detailHeight);
				boardArea = new java.awt.Rectangle(0, 0, w, h - detailHeight - GAP);
			}
			int side = Math.max(0, Math.min(boardArea.width, boardArea.height));
			grid.setBounds(boardArea.x + (boardArea.width - side) / 2, boardArea.y, side, side);
		}

		@Override
		public Dimension preferredLayoutSize(java.awt.Container parent)
		{
			return new Dimension(1040, 620);
		}

		@Override
		public Dimension minimumLayoutSize(java.awt.Container parent)
		{
			return new Dimension(400, 440);
		}

		@Override
		public void addLayoutComponent(String name, java.awt.Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(java.awt.Component comp)
		{
		}
	}

	/** Board title, a quiet subline (team, version) and a row of stat chips, over a gold rule. */
	private JPanel buildHeader()
	{
		titleLabel.setFont(FontManager.getRunescapeBoldFont());
		titleLabel.setForeground(Color.WHITE);
		subLabel.setFont(FontManager.getRunescapeSmallFont());
		subLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JPanel text = new JPanel(new GridLayout(2, 1, 0, 1));
		text.setOpaque(false);
		text.add(titleLabel);
		text.add(subLabel);

		JPanel chips = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		chips.setOpaque(false);
		for (BingoUi.Chip chip : new BingoUi.Chip[]{tilesChip, linesChip, pointsChip, rankChip, eventChip})
		{
			chips.add(chip);
			chips.add(Box.createHorizontalStrut(6));
		}

		JPanel header = new JPanel(new BorderLayout(0, 8));
		header.setOpaque(false);
		header.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, BingoUi.COLOR_GOLD.darker()),
			BorderFactory.createEmptyBorder(2, 2, 10, 2)));
		detailsShown = plugin.popOutDetailsShown();
		detailsToggle.setFocusable(false);
		detailsToggle.addActionListener(e -> setDetailsShown(!detailsShown));
		updateDetailsToggle();
		JPanel toggleHolder = new JPanel(new BorderLayout());
		toggleHolder.setOpaque(false);
		toggleHolder.add(detailsToggle, BorderLayout.NORTH);
		JPanel top = new JPanel(new BorderLayout(10, 0));
		top.setOpaque(false);
		top.add(text, BorderLayout.CENTER);
		top.add(toggleHolder, BorderLayout.EAST);
		header.add(top, BorderLayout.NORTH);
		header.add(chips, BorderLayout.CENTER);
		return header;
	}

	private void setChipsVisible(boolean visible)
	{
		tilesChip.setVisible(visible);
		linesChip.setVisible(visible);
		pointsChip.setVisible(visible);
		rankChip.setVisible(visible);
		eventChip.setVisible(visible);
	}

	private void updateStatusLine()
	{
		BingoBoard board = plugin.getBoard();
		if (board == null)
		{
			return;
		}
		setText(titleLabel, board.getName());
		String team = plugin.teamDisplayName();
		String sub = (team == null ? "No team set" : "Team " + team)
			+ (board.version != null ? "   ·   Board v" + board.version : "");
		setText(subLabel, sub);

		tilesChip.setVisible(true);
		tilesChip.set(plugin.completedCount() + " / " + board.getTiles().size(), "tiles", null);
		int lines = plugin.completedLines();
		linesChip.setVisible(true);
		linesChip.set(String.valueOf(lines), lines == 1 ? "line" : "lines", lines > 0 ? BingoUi.COLOR_GOLD : null);
		pointsChip.setVisible(plugin.totalBoardPoints() > 0);
		pointsChip.set(plugin.earnedPoints() + " / " + plugin.totalBoardPoints(), "pts", null);
		int rank = plugin.placementRank();
		rankChip.setVisible(rank > 0);
		if (rank > 0)
		{
			rankChip.set(BingoUi.ordinal(rank), "place", BingoUi.rankColor(rank));
		}
		String event = plugin.eventStatusText();
		eventChip.setVisible(!event.isEmpty());
		if (event.startsWith("Time left: "))
		{
			eventChip.set(event.substring("Time left: ".length()), "left", ColorScheme.BRAND_ORANGE);
		}
		else if (!event.isEmpty())
		{
			eventChip.set(event, null, ColorScheme.BRAND_ORANGE);
		}
		eventChip.setToolTipText(plugin.eventWindowTooltip());
	}

	private static void setText(JLabel label, String text)
	{
		if (!text.equals(label.getText()))
		{
			label.setText(text);
		}
	}

	private void rebuildGrid(BingoBoard board)
	{
		grid.removeAll();
		cells.clear();
		cellIcons.clear();
		cellLabels.clear();
		if (board == null)
		{
			grid.setLayout(new BorderLayout());
			JLabel hint = new JLabel("Import a board in the Irons Pub Bingo side panel first.", SwingConstants.CENTER);
			hint.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			grid.add(hint, BorderLayout.CENTER);
		}
		else
		{
			int size = board.getSize();
			grid.setLayout(new GridLayout(size, size, 4, 4));
			for (int i = 0; i < board.getTiles().size(); i++)
			{
				final int tileIndex = i;
				BingoTile tile = board.getTiles().get(i);
				BingoTileCell cell = new BingoTileCell();
				// Icon and text as separately stacked, individually centered components.
				// Swing's compound icon+text label does not center HTML text reliably.
				JLabel iconLabel = new JLabel();
				iconLabel.setAlignmentX(java.awt.Component.CENTER_ALIGNMENT);
				BingoWrappedLabel label = new BingoWrappedLabel(tile.label, SwingConstants.CENTER, 100);
				label.setForeground(Color.WHITE);
				if (tile.pointsValue() > 0)
				{
					label.setSecondary(tile.pointsValue() + " pts", ColorScheme.LIGHT_GRAY_COLOR);
				}
				AsyncBufferedImage itemIcon = plugin.iconFor(tile);
				if (itemIcon != null)
				{
					BingoUi.applyIcon(iconLabel, itemIcon, 32, cell);
				}
				JPanel stack = new JPanel();
				stack.setLayout(new javax.swing.BoxLayout(stack, javax.swing.BoxLayout.Y_AXIS));
				stack.setOpaque(false);
				stack.add(iconLabel);
				stack.add(javax.swing.Box.createVerticalStrut(4));
				stack.add(label);
				cell.setLayout(new java.awt.GridBagLayout());
				cell.add(stack, new java.awt.GridBagConstraints());
				cell.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
				// Tooltips register the children as mouse-event targets, so they must
				// carry the click handler too or they'd swallow clicks over icon/text.
				MouseAdapter click = new MouseAdapter()
				{
					@Override
					public void mousePressed(MouseEvent e)
					{
						plugin.selectTileInPanel(tileIndex);
						if (javax.swing.SwingUtilities.isRightMouseButton(e))
						{
							BingoUi.showTileMenu(plugin, tileIndex, e);
						}
					}
				};
				cell.addMouseListener(click);
				iconLabel.addMouseListener(click);
				label.addMouseListener(click);
				cell.trackHover(iconLabel);
				cell.trackHover(label);
				cells.add(cell);
				cellIcons.add(iconLabel);
				cellLabels.add(label);
				grid.add(cell);
			}
		}
		grid.revalidate();
		grid.repaint();
	}
}

package com.ironspubbingo;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;

/**
 * Agility courses whose laps can be counted: a lap completes when Agility XP lands while
 * the player stands on the course's end tile(s), with the course identified by map region.
 * This is the same detection RuneLite's own Agility plugin uses.
 *
 * Region ids and end tiles adapted from RuneLite's agility plugin Courses
 * (BSD-2, Copyright (c) 2018, Seth <http://github.com/sethtroll>).
 */
enum BingoCourse
{
	GNOME("Gnome Stronghold", 9781, point(2484, 3437, 0), point(2487, 3437, 0)),
	SHAYZIEN_BASIC("Shayzien Basic", 6200, point(1554, 3640, 0)),
	DRAYNOR("Draynor Village", 12338, point(3103, 3261, 0)),
	AL_KHARID("Al Kharid", 13105, point(3299, 3194, 0)),
	PYRAMID("Agility Pyramid", 13356, point(3364, 2830, 0)),
	VARROCK("Varrock", 12853, point(3236, 3417, 0)),
	PENGUIN("Penguin", 10559, point(2652, 4039, 1)),
	BARBARIAN("Barbarian Outpost", 10039, point(2543, 3553, 0)),
	CANIFIS("Canifis", 13878, point(3510, 3485, 0)),
	APE_ATOLL("Ape Atoll", 11050, point(2770, 2747, 0)),
	SHAYZIEN_ADVANCED("Shayzien Advanced", 5944, point(1522, 3625, 0)),
	FALADOR("Falador", 12084,
		point(3029, 3332, 0), point(3029, 3333, 0), point(3029, 3334, 0), point(3029, 3335, 0)),
	WILDERNESS("Wilderness", 11837,
		point(2993, 3933, 0), point(2994, 3933, 0), point(2995, 3933, 0)),
	WEREWOLF("Werewolf", 14234, point(3528, 9873, 0)),
	SEERS("Seers' Village", 10806, point(2704, 3464, 0)),
	POLLNIVNEACH("Pollnivneach", 13358, point(3363, 2998, 0)),
	RELLEKKA("Rellekka", 10553, point(2653, 3676, 0)),
	PRIFDDINAS("Prifddinas", 12895, point(3240, 6109, 0)),
	ARDOUGNE("Ardougne", 10547, point(2668, 3297, 0));

	private static final Map<Integer, BingoCourse> BY_REGION = new HashMap<>();
	private static final Map<String, BingoCourse> BY_NAME = new HashMap<>();

	private final String displayName;
	private final int regionId;
	private final WorldPoint[] endPoints;

	static
	{
		for (BingoCourse course : values())
		{
			BY_REGION.put(course.regionId, course);
			BY_NAME.put(normalize(course.name()), course);
			BY_NAME.put(normalize(course.displayName), course);
		}
		// Common spellings and shorthands hosts will type
		BY_NAME.put(normalize("Gnome"), GNOME);
		BY_NAME.put(normalize("Draynor"), DRAYNOR);
		BY_NAME.put(normalize("Seers"), SEERS);
		BY_NAME.put(normalize("Seers Village"), SEERS);
		BY_NAME.put(normalize("Relleka"), RELLEKKA);
		BY_NAME.put(normalize("Prif"), PRIFDDINAS);
		BY_NAME.put(normalize("Barbarian"), BARBARIAN);
		BY_NAME.put(normalize("Pyramid"), PYRAMID);
	}

	BingoCourse(String displayName, int regionId, WorldPoint... endPoints)
	{
		this.displayName = displayName;
		this.regionId = regionId;
		this.endPoints = endPoints;
	}

	private static WorldPoint point(int x, int y, int plane)
	{
		return new WorldPoint(x, y, plane);
	}

	private static String normalize(String value)
	{
		return value.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", "");
	}

	static BingoCourse fromName(String name)
	{
		return name == null ? null : BY_NAME.get(normalize(name));
	}

	static BingoCourse forRegion(int regionId)
	{
		return BY_REGION.get(regionId);
	}

	boolean isEndPoint(WorldPoint location)
	{
		for (WorldPoint end : endPoints)
		{
			if (end.equals(location))
			{
				return true;
			}
		}
		return false;
	}

	String getDisplayName()
	{
		return displayName;
	}
}

package com.ironspubbingo;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.util.ImageUtil;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Posts tile completions (message + screenshot) to a team's Discord webhook.
 * Opt-in via config; nothing is sent unless a webhook URL is set and the toggle is on.
 */
@Slf4j
@Singleton
class BingoDiscordNotifier
{
	private static final MediaType PNG = MediaType.parse("image/png");
	// How long a capture waits for the player to get past the welcome screen.
	private static final long CAPTURE_WAIT_MS = 120_000;
	// How long a capture waits for the requested frame to be drawn.
	private static final long FRAME_WAIT_SECONDS = 10;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private Gson gson;

	@Inject
	private DrawManager drawManager;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private IronsPubBingoConfig config;

	/** Timeouts still waiting to fire; cancelled on shutdown. */
	private final Set<ScheduledFuture<?>> pendingTimeouts = ConcurrentHashMap.newKeySet();

	/** Bumped on shutdown, so captures started before it give up. */
	private volatile int generation;

	/** Supplies a note when this client runs an outdated board, else null. Client thread. */
	private volatile java.util.function.Supplier<String> outdatedNote = () -> null;

	void setOutdatedNote(java.util.function.Supplier<String> note)
	{
		outdatedNote = note;
	}

	/** "\n:warning: Sent from an outdated board (v1, v2 is out)", or "" when current. */
	private String outdatedSuffix()
	{
		String note = outdatedNote.get();
		return note == null ? "" : "\n:warning: " + note;
	}

	/** Cancels pending timeouts and stops captures in progress. Called from the plugin's shutDown. */
	void shutDown()
	{
		generation++;
		for (ScheduledFuture<?> timeout : pendingTimeouts)
		{
			timeout.cancel(false);
		}
		pendingTimeouts.clear();
	}

	private void scheduleTimeout(Runnable task, long delay, TimeUnit unit)
	{
		pendingTimeouts.removeIf(ScheduledFuture::isDone);
		pendingTimeouts.add(executor.schedule(task, delay, unit));
	}

	/** Whether a webhook URL is set, so callers can offer webhook-backed features. */
	boolean webhookConfigured()
	{
		return HttpUrl.parse(config.webhookUrl().trim()) != null;
	}

	/**
	 * Posts one game screenshot to the webhook as proof for a credit request and hands
	 * back a link for the request's proof field. wait=true makes Discord return the
	 * created message, and the webhook's own metadata (a GET on its URL) gives the guild
	 * and channel, which turn the message id into a jump link. The jump link never
	 * expires; attachment CDN URLs do, so they are only the fallback.
	 * The callback gets (link, error) on an arbitrary thread.
	 */
	void postProofScreenshot(String player, String requestDetail, String team,
		java.util.function.BiConsumer<String, String> rawCallback)
	{
		// Exactly one answer, whatever happens: the request dialog waits on it. A client
		// that stops drawing frames (minimized) or a Discord reply that never parses
		// would otherwise leave the request unsent for the rest of the session.
		AtomicBoolean answered = new AtomicBoolean();
		java.util.function.BiConsumer<String, String> callback = (link, error) ->
		{
			if (answered.compareAndSet(false, true))
			{
				rawCallback.accept(link, error);
			}
		};
		scheduleTimeout(() -> callback.accept(null, "Screenshot timed out"), 60, TimeUnit.SECONDS);
		HttpUrl url = HttpUrl.parse(config.webhookUrl().trim());
		if (url == null)
		{
			callback.accept(null, "No Discord webhook set");
			return;
		}
		String content = ":camera_with_flash: **" + (player == null ? "Someone" : player)
			+ "** - credit request proof: " + requestDetail + teamSuffix(team) + outdatedSuffix();
		captureFrame(frame ->
		{
			Map<String, Object> payload = new HashMap<>();
			payload.put("content", content);
			MultipartBody.Builder body = new MultipartBody.Builder()
				.setType(MultipartBody.FORM)
				.addFormDataPart("payload_json", gson.toJson(payload));
			byte[] png = toPng(frame);
			if (png == null)
			{
				callback.accept(null, "Could not capture the screenshot");
				return;
			}
			body.addFormDataPart("files[0]", "proof.png", RequestBody.create(PNG, png));
			Request post = new Request.Builder()
				.url(url.newBuilder().setQueryParameter("wait", "true").build())
				.post(body.build())
				.build();
			okHttpClient.newCall(post).enqueue(new Callback()
			{
				@Override
				public void onFailure(Call call, IOException e)
				{
					callback.accept(null, "Discord unreachable: " + e.getMessage());
				}

				@Override
				public void onResponse(Call call, Response response) throws IOException
				{
					try (Response r = response)
					{
						if (!r.isSuccessful() || r.body() == null)
						{
							callback.accept(null, "Discord webhook returned " + r.code());
							return;
						}
						JsonObject message;
						try
						{
							message = gson.fromJson(r.body().string(), JsonObject.class);
						}
						catch (RuntimeException e)
						{
							message = null;
						}
						if (message == null)
						{
							callback.accept(null, "Discord sent an unreadable reply");
							return;
						}
						resolveMessageLink(url, message, callback);
					}
				}
			});
		});
	}

	/**
	 * Grabs a rendered frame for a screenshot, but not the very next one. One game tick
	 * later the "Bingo tile complete" line is in the chatbox and the loot is in the
	 * inventory, so the picture shows what it is proof of. And after a login the
	 * welcome screen is skipped: XP caught up from mobile completes tiles the moment the
	 * client logs in, when the next frame is the "Welcome to Gielinor" banner. Both
	 * checks retry frame by frame while the player is in the game, for up to two minutes.
	 * If they log out first, wait too long, or no frame is drawn (a minimized client),
	 * the post goes out without a picture.
	 */
	private void captureFrame(java.util.function.Consumer<Image> onFrame)
	{
		int[] startTick = {-1};
		int startGeneration = generation;
		long deadline = System.currentTimeMillis() + CAPTURE_WAIT_MS;
		AtomicBoolean delivered = new AtomicBoolean();
		java.util.function.Consumer<Image> deliver = frame ->
		{
			if (delivered.compareAndSet(false, true))
			{
				executor.execute(() -> onFrame.accept(frame));
			}
		};
		clientThread.invokeLater(() ->
		{
			if (generation != startGeneration)
			{
				return true; // the plugin shut down: drop the post
			}
			if (client.getGameState() != GameState.LOGGED_IN || System.currentTimeMillis() > deadline)
			{
				deliver.accept(null);
				return true;
			}
			if (startTick[0] < 0)
			{
				startTick[0] = client.getTickCount();
			}
			Widget play = client.getWidget(InterfaceID.WelcomeScreen.PLAY);
			boolean welcomeUp = play != null && !play.isHidden();
			boolean tickPassed = client.getTickCount() > startTick[0];
			if (welcomeUp || !tickPassed)
			{
				return false; // try again next frame
			}
			drawManager.requestNextFrameListener(deliver::accept);
			scheduleTimeout(() -> deliver.accept(null), FRAME_WAIT_SECONDS, TimeUnit.SECONDS);
			return true;
		});
	}

	/** Turns the webhook's reply into a permanent jump link, or the attachment URL. */
	private void resolveMessageLink(HttpUrl webhook, JsonObject message,
		java.util.function.BiConsumer<String, String> callback)
	{
		String messageId = message.has("id") ? message.get("id").getAsString() : null;
		String channelId = message.has("channel_id") ? message.get("channel_id").getAsString() : null;
		String attachmentUrl = null;
		if (message.has("attachments") && message.getAsJsonArray("attachments").size() > 0)
		{
			JsonObject attachment = message.getAsJsonArray("attachments").get(0).getAsJsonObject();
			attachmentUrl = attachment.has("url") ? attachment.get("url").getAsString() : null;
		}
		final String fallback = attachmentUrl;
		if (messageId == null || channelId == null)
		{
			finishWithLink(fallback, callback);
			return;
		}
		okHttpClient.newCall(new Request.Builder().url(webhook).get().build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				finishWithLink(fallback, callback);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (Response r = response)
				{
					String guildId = null;
					if (r.isSuccessful() && r.body() != null)
					{
						try
						{
							JsonObject info = gson.fromJson(r.body().string(), JsonObject.class);
							guildId = info != null && info.has("guild_id") ? info.get("guild_id").getAsString() : null;
						}
						catch (RuntimeException e)
						{
							guildId = null; // fall back to the attachment link
						}
					}
					finishWithLink(guildId == null ? fallback
						: "https://discord.com/channels/" + guildId + "/" + channelId + "/" + messageId, callback);
				}
			}
		});
	}

	private static void finishWithLink(String link, java.util.function.BiConsumer<String, String> callback)
	{
		if (link == null)
		{
			callback.accept(null, "Screenshot posted, but Discord gave no usable link");
		}
		else
		{
			callback.accept(link, null);
		}
	}

	/**
	 * Posts progress on a goal the host flagged with "screenshot": proof lands in Discord
	 * as it happens instead of one screenshot at tile completion. Rides the completion
	 * toggle and webhook - nothing extra to configure.
	 */
	// lootDetail: the drop that made this progress ("Uncut onyx from Zulrah"), or null.
	void postGoalProgress(String player, String tileLabel, String goalLabel, long progress, long target,
		String lootDetail, String team)
	{
		if (!config.postCompletions())
		{
			return;
		}
		HttpUrl url = HttpUrl.parse(config.webhookUrl().trim());
		if (url == null)
		{
			return;
		}
		String message = ":camera_with_flash: **" + (player == null ? "Someone" : player)
			+ "** - " + tileLabel + ": " + goalLabel
			+ " (" + progress + '/' + target + ')' + teamSuffix(team)
			+ (lootDetail == null ? "" : "\n:package: " + lootDetail) + outdatedSuffix();
		captureFrame(frame -> post(url, message, frame));
	}

	/** lootDetail: the drop (or valued loot pile) that finished the tile, or null. */
	void postCompletion(String player, String boardName, List<String> tileLabels, int completed, int total,
		String bonus, String lootDetail, String team)
	{
		if (!config.postCompletions())
		{
			return;
		}
		HttpUrl url = HttpUrl.parse(config.webhookUrl().trim());
		if (url == null)
		{
			return;
		}

		StringBuilder content = new StringBuilder();
		content.append(":tada: **").append(player == null ? "Someone" : player).append("** completed **")
			.append(String.join("**, **", tileLabels)).append("**").append(teamSuffix(team));
		content.append("\n").append(boardName).append(": ").append(completed).append('/').append(total).append(" tiles");
		if (lootDetail != null)
		{
			content.append("\n:package: ").append(lootDetail);
		}
		if (bonus != null)
		{
			content.append("\n:sparkles: ").append(bonus);
		}
		String message = content.append(outdatedSuffix()).toString();
		captureFrame(frame -> post(url, message, frame));
	}

	/** " for team **X**"; the caller resolves the display name (store > config > code). */
	private static String teamSuffix(String team)
	{
		return team == null || team.trim().isEmpty() ? "" : " for team **" + team.trim() + "**";
	}

	private void post(HttpUrl url, String message, Image frame)
	{
		Map<String, Object> payload = new HashMap<>();
		payload.put("content", message);

		MultipartBody.Builder body = new MultipartBody.Builder()
			.setType(MultipartBody.FORM)
			.addFormDataPart("payload_json", gson.toJson(payload));

		byte[] png = toPng(frame);
		if (png != null)
		{
			body.addFormDataPart("files[0]", "bingo.png", RequestBody.create(PNG, png));
		}

		Request request = new Request.Builder()
			.url(url)
			.post(body.build())
			.build();
		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Could not post bingo completion to Discord", e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				if (!response.isSuccessful())
				{
					log.warn("Discord webhook returned {}", response.code());
				}
				response.close();
			}
		});
	}

	/** null when there was no frame to capture (the player had logged out). */
	private static byte[] toPng(Image frame)
	{
		if (frame == null)
		{
			return null;
		}
		try
		{
			BufferedImage image = ImageUtil.bufferedImageFromImage(frame);
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			ImageIO.write(image, "png", out);
			return out.toByteArray();
		}
		catch (IOException e)
		{
			log.warn("Could not encode bingo screenshot", e);
			return null;
		}
	}
}

package com.ironspubbingo;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import net.runelite.api.Skill;

/**
 * One trackable condition inside a bingo tile, deserialized from the board JSON.
 * Which fields are relevant depends on {@link #type}; see the full Readme (docs/full-readme.md) for the schema.
 */
public class BingoGoal
{
	// -- deserialized from board JSON --
	/** Goal type name, case-insensitive; see {@link GoalType}. */
	String type;
	/** Optional label shown on the goal's progress bar instead of the generated one. */
	String name;
	/** DROP: item name globs to match. Empty/omitted = any item (rarely useful). */
	List<String> items;
	/** DROP/VALUE: loot source name globs (NPC or event name). Empty/omitted = any source. */
	List<String> sources;
	/** Target count (drops, purples, kills, pets, chat matches, qualifying value drops). Default 1. */
	Integer count;
	/** DROP: when true, each distinct item name counts once ("5 unique GWD drops"). */
	Boolean distinct;
	/** RAID_PURPLE: which raids count (COX/TOB/TOA). Empty/omitted = all three. */
	List<String> raids;
	/** KC: boss name globs matched against kill count chat messages. */
	List<String> npcs;
	/** PET: specific pet item name globs, matched via collection log messages. Empty/omitted = any pet. */
	List<String> pets;
	/** XP: skill name, e.g. "SLAYER". */
	String skill;
	/** LAP: agility course name, e.g. "Canifis". */
	String course;
	/** XP: experience to gain. VALUE: minimum GE value of a single loot pile, in gp. */
	Long amount;
	/** CHAT: regex matched against game messages. */
	String pattern;
	/** DROP: exact item ids, for items sharing a name with something else. ORed with items. */
	List<Integer> itemIds;
	/** DROP/VALUE: which loot kinds count - KILL, PICKPOCKET, OTHER. Omitted/empty = all. */
	List<String> loot;
	/** CHAT: map region ids the player must be in. Empty/omitted = anywhere. */
	List<Integer> regions;
	/** When true, progress on this goal posts a screenshot to the Discord webhook. */
	Boolean screenshot;

	/** How a piece of loot reached the player, for goals restricted by {@link #loot}. */
	enum LootKind
	{
		/** Awarded for an NPC kill. */
		KILL,
		/** Pickpocketed. */
		PICKPOCKET,
		/** Everything else: chests, caskets, events, PvP, marks of grace. */
		OTHER
	}

	// -- resolved during validation --
	transient GoalType goalType;
	transient List<Pattern> itemPatterns;
	transient List<Pattern> sourcePatterns;
	transient List<Pattern> npcPatterns;
	transient List<Pattern> petPatterns;
	transient Pattern chatPattern;
	transient EnumSet<Raid> raidSet;
	transient Skill skillEnum;
	transient BingoCourse courseEnum;
	transient EnumSet<LootKind> lootSet;

	/**
	 * Resolves string fields into their typed forms.
	 *
	 * @return an error message, or null if the goal is valid
	 */
	String validate()
	{
		if (type == null || type.trim().isEmpty())
		{
			return "missing goal type";
		}
		try
		{
			goalType = GoalType.valueOf(type.trim().toUpperCase(Locale.ROOT));
		}
		catch (IllegalArgumentException e)
		{
			return "unknown goal type '" + type + "'";
		}

		itemPatterns = Wildcards.compileAll(items);
		sourcePatterns = Wildcards.compileAll(sources);
		npcPatterns = Wildcards.compileAll(npcs);
		petPatterns = Wildcards.compileAll(pets);

		switch (goalType)
		{
			case DROP:
				if (itemPatterns.isEmpty() && (itemIds == null || itemIds.isEmpty()))
				{
					return "DROP goal needs at least one entry in 'items' or 'itemIds'";
				}
				break;
			case KC:
				if (npcPatterns.isEmpty())
				{
					return "KC goal needs at least one entry in 'npcs'";
				}
				break;
			case KILL:
				if (npcPatterns.isEmpty())
				{
					return "KILL goal needs at least one entry in 'npcs'";
				}
				break;
			case RAID_PURPLE:
				if (raids == null || raids.isEmpty())
				{
					raidSet = EnumSet.allOf(Raid.class);
				}
				else
				{
					raidSet = EnumSet.noneOf(Raid.class);
					for (String r : raids)
					{
						try
						{
							raidSet.add(Raid.valueOf(r.trim().toUpperCase(Locale.ROOT)));
						}
						catch (IllegalArgumentException e)
						{
							return "unknown raid '" + r + "' (use COX, TOB or TOA)";
						}
					}
				}
				break;
			case XP:
				if (skill == null)
				{
					return "XP goal needs a 'skill'";
				}
				try
				{
					skillEnum = Skill.valueOf(skill.trim().toUpperCase(Locale.ROOT));
				}
				catch (IllegalArgumentException e)
				{
					return "unknown skill '" + skill + "'";
				}
				if (amount == null || amount <= 0)
				{
					return "XP goal needs a positive 'amount'";
				}
				break;
			case VALUE:
				if (amount == null || amount <= 0)
				{
					return "VALUE goal needs a positive 'amount' (gp)";
				}
				break;
			case LAP:
				if (course == null || course.trim().isEmpty())
				{
					return "LAP goal needs a 'course'";
				}
				courseEnum = BingoCourse.fromName(course);
				if (courseEnum == null)
				{
					return "unknown agility course '" + course + "'";
				}
				break;
			case CHAT:
				if (pattern == null || pattern.trim().isEmpty())
				{
					return "CHAT goal needs a 'pattern'";
				}
				try
				{
					chatPattern = Pattern.compile(pattern, Pattern.CASE_INSENSITIVE);
				}
				catch (PatternSyntaxException e)
				{
					return "invalid regex in 'pattern': " + e.getDescription();
				}
				break;
			case PET:
			case MANUAL:
				break;
		}
		if ((goalType == GoalType.DROP || goalType == GoalType.VALUE) && loot != null && !loot.isEmpty())
		{
			lootSet = EnumSet.noneOf(LootKind.class);
			for (String kind : loot)
			{
				try
				{
					lootSet.add(LootKind.valueOf(kind.trim().toUpperCase(Locale.ROOT)));
				}
				catch (IllegalArgumentException e)
				{
					return "unknown 'loot' kind '" + kind + "' (use KILL, PICKPOCKET or OTHER)";
				}
			}
		}
		if (count != null && count <= 0)
		{
			return "'count' must be positive";
		}
		return null;
	}

	boolean isDistinct()
	{
		return distinct != null && distinct;
	}

	/** The value {@link GoalProgress} must reach for this goal to be complete. */
	long target()
	{
		if (goalType == GoalType.XP)
		{
			return amount;
		}
		if (goalType == GoalType.MANUAL)
		{
			return 1;
		}
		return count == null ? 1 : count;
	}

	/** Whether this goal counts distinct names via the matched set rather than the plain counter. */
	boolean usesMatchedSet()
	{
		return ((goalType == GoalType.DROP || goalType == GoalType.RAID_PURPLE) && isDistinct())
			|| (goalType == GoalType.PET && !petPatterns.isEmpty());
	}

	/**
	 * DROP: whether this item counts. Ids beat globs for items whose display name is
	 * shared (the two "Loop half of key" items); with only ids listed, names don't match.
	 */
	boolean matchesItem(String itemName, int canonicalId)
	{
		if (itemIds != null && itemIds.contains(canonicalId))
		{
			return true;
		}
		if (itemPatterns.isEmpty())
		{
			// No name globs: with ids listed this goal is id-only, otherwise any item counts.
			return itemIds == null || itemIds.isEmpty();
		}
		return Wildcards.anyMatch(itemPatterns, itemName);
	}

	/** DROP: whether loot that arrived this way counts for the goal. */
	boolean allowsLoot(LootKind kind)
	{
		return lootSet == null || lootSet.contains(kind);
	}

	/** CHAT: whether the goal counts in this map region (either of the two candidate ids). */
	boolean allowsRegion(int worldRegion, int instanceRegion)
	{
		return regions == null || regions.isEmpty()
			|| regions.contains(worldRegion) || regions.contains(instanceRegion);
	}

	boolean wantsScreenshot()
	{
		return screenshot != null && screenshot;
	}

	long progressOf(GoalProgress p)
	{
		if (usesMatchedSet())
		{
			// Tracking only ever fills the name set; the counter on a distinct goal is
			// admin credit from the store ("add 2"), which has no names to contribute.
			return (p.matched == null ? 0 : p.matched.size()) + p.n;
		}
		return p.n;
	}

	boolean isComplete(GoalProgress p)
	{
		return goalType != GoalType.MANUAL && progressOf(p) >= target();
	}

	/**
	 * What this goal TRACKS, canonically. Targets (count, XP amount) are excluded on
	 * purpose: hosts may tune how much without resetting anyone. When a tile's combined
	 * signature changes, its stored numbers describe something else and are reset.
	 */
	String trackingSignature()
	{
		List<String> parts = new ArrayList<>();
		parts.add(goalType.name());
		parts.add(sigNames(items));
		parts.add(sigNumbers(itemIds));
		parts.add(sigNames(sources));
		parts.add(sigNames(loot));
		parts.add(isDistinct() ? "distinct" : "");
		parts.add(sigNames(raids));
		parts.add(sigNames(npcs));
		parts.add(sigNames(pets));
		parts.add(skill == null ? "" : skill.trim().toUpperCase(Locale.ROOT));
		parts.add(course == null ? "" : course.trim().toUpperCase(Locale.ROOT));
		parts.add(pattern == null ? "" : pattern);
		parts.add(sigNumbers(regions));
		return String.join("|", parts);
	}

	/** Sorted so reordering a list (same meaning) never looks like a different goal. */
	private static String sigNames(List<String> values)
	{
		if (values == null || values.isEmpty())
		{
			return "";
		}
		List<String> cleaned = new ArrayList<>();
		for (String value : values)
		{
			if (value != null && !value.trim().isEmpty())
			{
				cleaned.add(value.trim().toLowerCase(Locale.ROOT));
			}
		}
		java.util.Collections.sort(cleaned);
		return String.join(",", cleaned);
	}

	private static String sigNumbers(List<Integer> values)
	{
		if (values == null || values.isEmpty())
		{
			return "";
		}
		List<Integer> sorted = new ArrayList<>(values);
		java.util.Collections.sort(sorted);
		StringBuilder joined = new StringBuilder();
		for (Integer value : sorted)
		{
			joined.append(joined.length() > 0 ? "," : "").append(value);
		}
		return joined.toString();
	}

	/** Longest goal label shown in full; longer ones compact and move detail behind the toggle. */
	private static final int MAX_LABEL_LENGTH = 46;

	/**
	 * Goal label for the panel. Short goals ("Drops: Egg") are shown in full; only long
	 * ones compact to a summary ("Distinct drops from Chicken") and move their item and
	 * source lists into the collapsible details box.
	 */
	String shortDescribe()
	{
		if (name != null && !name.trim().isEmpty())
		{
			return name.trim();
		}
		String full = describe();
		if (full.length() <= MAX_LABEL_LENGTH)
		{
			return full;
		}
		switch (goalType)
		{
			case DROP:
				return (isDistinct() ? "Distinct " + dropNoun().toLowerCase(Locale.ROOT) : dropNoun()) + fromSources();
			case RAID_PURPLE:
				return "Raid purples (" + raidSet.toString().replaceAll("[\\[\\]]", "") + ")";
			case KC:
			case KILL:
				return npcs.size() == 1 ? "Kills: " + pretty(npcs.get(0)) : "Kills (" + npcs.size() + " targets)";
			case PET:
				return petPatterns.isEmpty() ? "Any pet"
					: pets.size() == 1 ? "Pet: " + pretty(pets.get(0)) : "Pets (" + pets.size() + ")";
			case XP:
				return skillEnum.getName() + " XP";
			case LAP:
				return courseEnum.getDisplayName() + " laps";
			case VALUE:
				return "Big drop" + fromSources();
			case CHAT:
				return "Game message";
			case MANUAL:
			default:
				return "Manual tile";
		}
	}

	/** Whether the full description says more than the label already shows. */
	boolean hasExtraDetail()
	{
		return !describe().equals(shortDescribe());
	}

	/** "Drops", "Kill drops" or "Pickpocket loot", per the goal's loot restriction. */
	private String dropNoun()
	{
		if (lootSet != null && lootSet.equals(EnumSet.of(LootKind.PICKPOCKET)))
		{
			return "Pickpocket loot";
		}
		if (lootSet != null && lootSet.equals(EnumSet.of(LootKind.KILL)))
		{
			return "Kill drops";
		}
		return "Drops";
	}

	private String fromSources()
	{
		if (sources == null || sources.isEmpty())
		{
			return "";
		}
		return sources.size() == 1 ? " from " + pretty(sources.get(0)) : " from " + sources.size() + " sources";
	}

	/** Full human-readable description of the goal, for the details box and tooltips. */
	String describe()
	{
		switch (goalType)
		{
			case DROP:
				// A goal may match by id alone, with no names to print.
				String matched = prettyJoin(items);
				if (matched.isEmpty() && itemIds != null && !itemIds.isEmpty())
				{
					matched = itemIds.size() == 1 ? "item " + itemIds.get(0) : itemIds.size() + " item ids";
				}
				return (isDistinct() ? "Distinct " + dropNoun().toLowerCase(Locale.ROOT) : dropNoun()) + ": " + matched
					+ (sources == null || sources.isEmpty() ? "" : " from " + prettyJoin(sources));
			case RAID_PURPLE:
				return "Raid purples (" + raidSet.toString().replaceAll("[\\[\\]]", "") + ")";
			case KC:
			case KILL:
				return "Kills: " + prettyJoin(npcs);
			case PET:
				return petPatterns.isEmpty() ? "Any pet" : "Pets: " + prettyJoin(pets);
			case XP:
				return String.format("%,d %s XP", amount, skillEnum.getName());
			case LAP:
				return courseEnum.getDisplayName() + " course laps";
			case VALUE:
				return String.format("Drop worth %,d+ gp", amount)
					+ (sources == null || sources.isEmpty() ? "" : " from " + prettyJoin(sources));
			case CHAT:
				String readable = readablePattern(pattern);
				return readable != null ? readable : "Game message";
			case MANUAL:
			default:
				return "Manual (tick off by hand)";
		}
	}

	/** Name globs read better without their wildcards: "3rd age*" -> "3rd age". */
	private static String pretty(String glob)
	{
		return glob.replace("*", " ").replaceAll("\\s+", " ").trim();
	}

	private static String prettyJoin(List<String> values)
	{
		List<String> cleaned = new ArrayList<>();
		if (values == null)
		{
			return "";
		}
		for (String value : values)
		{
			String clean = pretty(value);
			if (!clean.isEmpty())
			{
				cleaned.add(clean);
			}
		}
		return String.join(", ", cleaned);
	}

	/**
	 * Turns a chat regex into something a player can read, by keeping its literal text and
	 * marking where the variable parts are: "You have completed [0-9,]+ elite Treasure
	 * Trails" becomes "You have completed ... elite Treasure Trails". Returns null when
	 * nothing readable is left.
	 */
	static String readablePattern(String regex)
	{
		String[] parts = regex.split("\\[[^\\]]*\\][*+?]?|\\([^)]*\\)[*+?]?|\\\\[a-zA-Z]|\\{\\d+(,\\d+)?\\}|[.*+?^$|]");
		List<String> literals = new ArrayList<>();
		for (String part : parts)
		{
			String cleaned = part.replaceAll("\\\\(.)", "$1")
				.replaceAll("\\s+", " ")
				.replaceAll("^[\\s:;,\\-]+|[\\s:;,\\-]+$", "");
			if (cleaned.length() >= 4)
			{
				literals.add(cleaned);
			}
		}
		return literals.isEmpty() ? null : String.join(" ... ", literals);
	}
}

package com.ironspubbingo;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.Collections;
import java.util.List;
import javax.swing.JPanel;

/**
 * The bingo grid container: hosts the tile cells and paints translucent strokes straight
 * through completed bingo lines on top of them, classic bingo-card style, so it is obvious
 * which row/column/diagonal a completed line runs along.
 */
class BingoGridPanel extends JPanel
{
	private int boardSize;
	/** Completed lines as {firstCellIndex, lastCellIndex} pairs. */
	private List<int[]> lineSegments = Collections.emptyList();
	private Color lineColor = BingoUi.COLOR_LINE;

	void setLines(int boardSize, List<int[]> lineSegments, Color color)
	{
		this.boardSize = boardSize;
		this.lineSegments = lineSegments;
		// Translucent, so the tile icons show through the stroke.
		this.lineColor = new Color(color.getRed(), color.getGreen(), color.getBlue(), 110);
		repaint();
	}

	@Override
	protected void paintChildren(Graphics g)
	{
		super.paintChildren(g);
		if (lineSegments.isEmpty() || boardSize <= 0 || getComponentCount() < boardSize * boardSize)
		{
			return;
		}
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setColor(lineColor);
		g2.setStroke(new BasicStroke(Math.max(2.5f, getWidth() / (boardSize * 28f)),
			BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		for (int[] segment : lineSegments)
		{
			Point from = cellCenter(segment[0]);
			Point to = cellCenter(segment[1]);
			// A segment from a board swapped in mid-redraw can name cells this grid lacks.
			if (from != null && to != null)
			{
				g2.drawLine(from.x, from.y, to.x, to.y);
			}
		}
		g2.dispose();
	}

	/** The center of a cell, or null when the grid has no such cell. */
	private Point cellCenter(int cellIndex)
	{
		if (cellIndex < 0 || cellIndex >= getComponentCount())
		{
			return null;
		}
		Rectangle bounds = getComponent(cellIndex).getBounds();
		return new Point(bounds.x + bounds.width / 2, bounds.y + bounds.height / 2);
	}
}

