	private static String page(String title, String body)
	{
		return "<html><body style='margin:0'>"
			+ "<div style='color:" + GOLD + "; font-size:15pt; font-weight:bold; margin-bottom:6px'>" + title + "</div>"
			+ body + "</body></html>";
	}

	private static String h(String text)
	{
		return "<div style='color:#ffffff; font-weight:bold; margin-top:12px; margin-bottom:2px'>" + text + "</div>";
	}

	private static String p(String text)
	{
		return "<p style='margin-top:6px; margin-bottom:4px'>" + text + "</p>";
	}

	private static String ul(String... items)
	{
		StringBuilder out = new StringBuilder("<ul style='margin-top:4px; margin-left:18px'>");
		for (String item : items)
		{
			out.append("<li style='margin-bottom:5px'>").append(item).append("</li>");
		}
		return out.append("</ul>").toString();
	}

	private static String ol(String... items)
	{
		StringBuilder out = new StringBuilder("<ol style='margin-top:4px; margin-left:22px'>");
		for (String item : items)
		{
			out.append("<li style='margin-bottom:5px'>").append(item).append("</li>");
		}
		return out.append("</ol>").toString();
	}

	/** The tile colors, as small swatches with what they mean. */
	private static String legend(Color lineColor)
	{
		Color line = lineColor == null ? BingoUi.COLOR_LINE : lineColor;
		String lineHex = String.format("#%02x%02x%02x", line.getRed(), line.getGreen(), line.getBlue());
		return "<table cellspacing='0' cellpadding='3' style='margin-top:4px; margin-bottom:6px'>"
			+ swatch("#2c2c2c", "No progress yet")
			+ swatch("#96701a", "Some progress")
			+ swatch("#42843a", "Complete")
			+ swatch(lineHex, "A completed bingo line. Line style and Line color in the settings change how it looks.")
			+ "</table>";
	}

	private static String swatch(String color, String meaning)
	{
		return "<tr><td bgcolor='" + color + "' width='18'>&nbsp;</td><td style='color:" + MUTED
			+ "; padding-left:8px'>" + meaning + "</td></tr>";
	}
}

package com.ironspubbingo;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * The tiles a player pinned from the board (right-click a tile), with a bar per goal,
 * so progress shows without opening the sidebar.
 */
class BingoPinnedTileOverlay extends OverlayPanel
{
	private static final int WIDTH = 200;
	/** The panel's border leaves this much room for text. */
	private static final int TEXT_WIDTH = WIDTH - 10;
	private static final Color BAR_BACKGROUND = new Color(54, 40, 26);
	private static final Color DIVIDER = new Color(90, 80, 68);

	private final IronsPubBingoPlugin plugin;
	private final IronsPubBingoConfig config;

	@Inject
	BingoPinnedTileOverlay(IronsPubBingoPlugin plugin, IronsPubBingoConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		BingoBoard board = plugin.getBoard();
		List<Integer> pinned = config.overlayPinnedTiles() ? plugin.pinnedTiles() : null;
		if (board == null || pinned == null || pinned.isEmpty())
		{
			return null;
		}
		panelComponent.setPreferredSize(new Dimension(WIDTH, 0));
		// Room below each line, so a bar never covers the tails of letters like g and y.
		panelComponent.setGap(new Point(0, 3));
		FontMetrics metrics = graphics.getFontMetrics();
		boolean hideCompleted = config.overlayHideCompletedPins();
		boolean first = true;
		for (int index : pinned)
		{
			if (index < 0 || index >= board.getTiles().size())
			{
				continue;
			}
			BingoTile tile = board.getTiles().get(index);
			TileProgress merged = plugin.mergedProgressFor(index);
			boolean complete = tile.isComplete(merged);
			if (complete && hideCompleted)
			{
				// Still pinned: it shows again if the setting is turned off or the tile reopens.
				continue;
			}
			if (!first)
			{
				panelComponent.getChildren().add(new Divider());
			}
			first = false;
			panelComponent.getChildren().add(TitleComponent.builder()
				.text(fit(metrics, tile.label))
				.color(complete ? BingoUi.COLOR_GOAL_DONE : ColorScheme.BRAND_ORANGE)
				.build());
			for (int g = 0; g < tile.goals.size(); g++)
			{
				BingoGoal goal = tile.goals.get(g);
				GoalProgress p = merged.goal(g, tile.goals.size());
				long target = goal.goalType == GoalType.MANUAL ? 1 : goal.target();
				long value = merged.manual ? target
					: goal.goalType == GoalType.MANUAL ? 0
					// A goal's number never shows past its target, nor below zero.
					: Math.max(0, Math.min(goal.progressOf(p), target));
				boolean done = merged.manual || goal.isComplete(p);
				panelComponent.getChildren().add(LineComponent.builder()
					.left(fit(metrics, plugin.goalLabel(goal)))
					.leftColor(done ? BingoUi.COLOR_GOAL_DONE : Color.WHITE)
					.build());
				ProgressBarComponent bar = new ProgressBarComponent();
				bar.setMinimum(0);
				bar.setMaximum(Math.max(1, target));
				bar.setValue(value);
				bar.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.FULL);
				bar.setForegroundColor(done ? BingoUi.COLOR_COMPLETE : BingoUi.COLOR_PARTIAL);
				bar.setBackgroundColor(BAR_BACKGROUND);
				panelComponent.getChildren().add(bar);
			}
		}
		if (first)
		{
			// Every pinned tile is hidden: no empty box.
			panelComponent.getChildren().clear();
			return null;
		}
		return super.render(graphics);
	}

	/** Cuts text that would run past the box, ending it with "...". */
	private static String fit(FontMetrics metrics, String text)
	{
		if (text == null || metrics.stringWidth(text) <= TEXT_WIDTH)
		{
			return text;
		}
		int end = text.length();
		while (end > 0 && metrics.stringWidth(text.substring(0, end) + "...") > TEXT_WIDTH)
		{
			end--;
		}
		return text.substring(0, end).trim() + "...";
	}

	/** A thin line between two pinned tiles. */
	private static class Divider implements LayoutableRenderableEntity
	{
		private static final int HEIGHT = 7;
		private final Rectangle bounds = new Rectangle();
		private Point location = new Point();
		private Dimension size = new Dimension(TEXT_WIDTH, HEIGHT);

		@Override
		public Dimension render(Graphics2D graphics)
		{
			graphics.setColor(DIVIDER);
			int y = location.y + HEIGHT / 2;
			graphics.drawLine(location.x, y, location.x + size.width - 1, y);
			Dimension dimension = new Dimension(size.width, HEIGHT);
			bounds.setLocation(location);
			bounds.setSize(dimension);
			return dimension;
		}

		@Override
		public Rectangle getBounds()
		{
			return bounds;
		}

		@Override
		public void setPreferredLocation(Point position)
		{
			location = position;
		}

		@Override
		public void setPreferredSize(Dimension dimension)
		{
			if (dimension != null && dimension.width > 0)
			{
				size = new Dimension(dimension.width, HEIGHT);
			}
		}
	}
}

package com.ironspubbingo;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * The in-game status box: sync problems and the event countdown, each
 * with its own setting. It hides when there is nothing to say.
 */
class BingoStatusOverlay extends OverlayPanel
{
	private static final Color PROBLEM = new Color(255, 70, 70);

	private final IronsPubBingoPlugin plugin;
	private final IronsPubBingoConfig config;

	@Inject
	BingoStatusOverlay(IronsPubBingoPlugin plugin, IronsPubBingoConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		String store = config.overlayStoreWarning() ? plugin.storeOverlayWarning() : null;
		String live = config.overlayLiveSyncWarning() ? plugin.liveSyncOverlayWarning() : null;
		String countdown = config.overlayCountdown() ? plugin.eventCountdownOverlayText() : null;
		if (store == null && live == null && countdown == null)
		{
			return null;
		}
		panelComponent.setPreferredSize(new Dimension(230, 0));
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Irons Pub Bingo")
			.color(ColorScheme.BRAND_ORANGE)
			.build());
		if (countdown != null)
		{
			panelComponent.getChildren().add(LineComponent.builder().left(countdown).build());
		}
		if (store != null)
		{
			addProblem("Store: " + store);
		}
		if (live != null)
		{
			addProblem("Live sync: " + live);
		}
		return super.render(graphics);
	}

	/**
	 * A problem in red. What to do about it ("use Import from store") follows the
	 * " - " in the text and stays white on its own line.
	 */
	private void addProblem(String text)
	{
		int cut = text.indexOf(" - ");
		String problem = cut < 0 ? text : text.substring(0, cut);
		panelComponent.getChildren().add(LineComponent.builder().left(problem).leftColor(PROBLEM).build());
		if (cut >= 0)
		{
			String fix = text.substring(cut + 3);
			panelComponent.getChildren().add(LineComponent.builder()
				.left(Character.toUpperCase(fix.charAt(0)) + fix.substring(1)).build());
		}
	}
}

package com.ironspubbingo;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import java.util.function.BiConsumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Optional persistent team store (Layer 3 of team sync): POSTs everything this client
 * knows about the team to a host-configured URL and receives the server's merged view
 * back in the same call, so members whose play times never overlap still exchange
 * progress. The backend is the Cloudflare Worker in cloudflare-store/ that the bingo host
 * deploys. Opt-in: nothing is sent unless a URL is set and the toggle is enabled.
 */
@Slf4j
@Singleton
class BingoTeamStore
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	/**
	 * Generous timeout: a slow connection must not turn a sync that the store did receive
	 * into an error the plugin retries.
	 */
	private static final long TIMEOUT_SECONDS = 45;

	@Inject
	private OkHttpClient okHttpClient;

	private OkHttpClient storeClient;

	/** The logged-in account's member key, sent with every request (null logged out). */
	private volatile String memberKey;

	@Inject
	private Gson gson;

	@Inject
	private IronsPubBingoConfig config;

	/** One host-defined team from the store's Teams list. */
	static class TeamInfo
	{
		String code;
		String name;
		/** Display names signed up under this team on the client's board, for the picker. */
		List<String> members;
	}

	/** One team's score on the shared board, for the placement display. */
	static class Standing
	{
		String team;
		Integer points;
	}

	/** A member's plea for admin credit, reviewed by an admin on the store. */
	static class CreditRequest
	{
		String member;
		String player;
		int tile;       // 1-based, as shown on the Board tab
		Integer goal;   // 1-based, null for single-goal tiles
		Long add;
		boolean complete;
		String note;
		/** Link(s) to screenshot proof (Discord/Imgur), whitespace separated. */
		String links;
	}

	/** Wire format: request and response bodies are both this shape (unused fields null). */
	static class StorePayload
	{
		String board;
		Map<String, TeamMemberState> members;
		/** Board definition (labels, targets), so the store can render a readable view. */
		Object meta;
		/** Request: member ids to evict from this board scope (player left the team). */
		List<String> remove;
		/** Response: every id evicted from this board scope; clients must drop these. */
		List<String> removed;
		/** Response: the host-defined team list (empty/absent = host allows any code). */
		List<TeamInfo> teams;
		/** Request: only fetch the team list, no board data. */
		Boolean teamsOnly;
		/** Request: fetch the board code the host saved on the store. */
		Boolean fetchBoard;
		/** Response to fetchBoard: the board code, ready for the normal import path. */
		String boardJson;
		/**
		 * Request: the sender's own member id. Clears any "left the team" tombstone for it
		 * in this scope, so someone who switches back to a team they left heals themselves.
		 * Admin-added (hand-written) tombstones are not cleared by this.
		 */
		String rejoin;
		/** Request: a credit request for the admins' Requests tab. */
		CreditRequest request;
		/** Response: host-set seconds between store polls (Settings tab); 0/null = default. */
		Integer pollSeconds;
		/** Response: the store's generation, bumped whenever the host resets it. */
		Integer epoch;
		/** Request: this team's current total points, for the cross-team standings. */
		Integer teamPoints;
		/** Request: fingerprint of the sender's board code; must match the host's, if set. */
		String boardHash;
		/** Request: the sender's board version, so an outdated client is told to update. */
		Integer boardVersion;
		/** Response: every team's points on this board, sorted best first. */
		List<Standing> standings;
		/** Response: why the push was rejected (e.g. a team code the host didn't define). */
		String error;
		/** Response beside a "Board updated" rejection: the version the host pasted. */
		Integer newerVersion;
		/**
		 * Request: proof that the sender is the member it syncs as. Derived from the
		 * account on this client, so it is the same on every machine the player uses,
		 * and it cannot be computed from the public member id.
		 */
		String memberKey;

		StorePayload(String board, Map<String, TeamMemberState> members, Object meta)
		{
			this.board = board;
			this.members = members;
			this.meta = meta;
		}
	}

	/** The client's OkHttp instance with timeouts raised for cold starts. */
	private OkHttpClient client()
	{
		if (storeClient == null)
		{
			storeClient = okHttpClient.newBuilder()
				.connectTimeout(TIMEOUT_SECONDS, TimeUnit.SECONDS)
				.readTimeout(TIMEOUT_SECONDS, TimeUnit.SECONDS)
				.writeTimeout(TIMEOUT_SECONDS, TimeUnit.SECONDS)
				.callTimeout(TIMEOUT_SECONDS, TimeUnit.SECONDS)
				.build();
		}
		return storeClient;
	}

	boolean isConfigured()
	{
		return config.teamStoreEnabled() && hasUrl();
	}

	/** Whether a store URL is set, regardless of the sync toggle. */
	boolean hasUrl()
	{
		return HttpUrl.parse(config.teamSyncUrl().trim()) != null;
	}

	/**
	 * Pushes the given state and hands the server's reply to the callback. On success the
	 * payload carries the merged team view (plus the host's team list and evicted ids);
	 * on failure the payload is null (or, for a store-side rejection, carries the team
	 * list alongside the error). The callback runs on an OkHttp thread, so hop to the
	 * client thread before touching plugin state.
	 */
	void sync(String board, Map<String, TeamMemberState> members, Object meta, String selfId,
		int teamPoints, String boardHash, Integer boardVersion, BiConsumer<StorePayload, String> callback)
	{
		StorePayload request = new StorePayload(board, members, meta);
		request.rejoin = selfId;
		request.teamPoints = teamPoints;
		request.boardHash = boardHash;
		request.boardVersion = boardVersion;
		post(request, (payload, error) ->
		{
			if (error != null || payload == null)
			{
				callback.accept(null, error != null ? error : "Unexpected reply");
			}
			else if (payload.error != null)
			{
				callback.accept(payload, payload.error);
			}
			else if (payload.members == null)
			{
				callback.accept(null, "Empty reply");
			}
			else if (!board.equals(payload.board))
			{
				log.debug("Store replied for board {} but we asked for {}", payload.board, board);
				callback.accept(null, "Mismatched reply");
			}
			else
			{
				callback.accept(payload, null);
			}
		});
	}

	/**
	 * Tells the store this member left the given board scope: their row is deleted and the
	 * id tombstoned so cached copies pushed by teammates can't bring it back. The caller
	 * persists and retries until {@code onSuccess} runs (on an OkHttp thread).
	 */
	void remove(String board, String memberId, Runnable onSuccess)
	{
		StorePayload payload = new StorePayload(board, java.util.Collections.emptyMap(), null);
		payload.remove = java.util.Collections.singletonList(memberId);
		// Requires only the URL, not the sync toggle: leaving a store team by turning the
		// toggle OFF must still deliver this one departure notice, or the old team would
		// keep counting the player. No other traffic happens while the toggle is off.
		post(payload, false, (reply, error) ->
		{
			// "Busy" and other store errors arrive as replies too: only a clean reply
			// means the departure landed, anything else is retried later.
			String problem = error != null ? error : reply == null ? "no reply" : reply.error;
			if (problem != null)
			{
				log.debug("Could not remove member from old team scope yet: {}", problem);
			}
			else
			{
				onSuccess.run();
			}
		});
	}

	/** Files a credit request onto the admins' Requests tab. Callback gets (ok, error). */
	// The board fingerprint rides along: requests pass the store's tamper gate too.
	void submitRequest(String board, CreditRequest request, String boardHash, Integer boardVersion,
		BiConsumer<Boolean, String> callback)
	{
		StorePayload payload = new StorePayload(board, java.util.Collections.emptyMap(), null);
		payload.request = request;
		payload.boardHash = boardHash;
		payload.boardVersion = boardVersion;
		post(payload, (reply, error) ->
		{
			String problem = error != null ? error : reply != null ? reply.error : null;
			callback.accept(problem == null, problem);
		});
	}

	/** Fetches the board code the host saved on the store. Callback gets (json, error). */
	void fetchBoard(BiConsumer<String, String> callback)
	{
		StorePayload payload = new StorePayload(null, null, null);
		payload.fetchBoard = true;
		post(payload, (reply, error) ->
		{
			String problem = error != null ? error : reply == null ? "Unexpected reply"
				: reply.error != null ? reply.error
				: reply.boardJson == null || reply.boardJson.isEmpty() ? "Unexpected reply" : null;
			callback.accept(problem == null ? reply.boardJson : null, problem);
		});
	}

	/** Fetches the host-defined team list (Teams tab); empty when the host defined none. */
	// The board key (nullable) scopes each team's member names to the client's board.
	void fetchTeams(String boardKey, BiConsumer<List<TeamInfo>, String> callback)
	{
		StorePayload payload = new StorePayload(boardKey, null, null);
		payload.teamsOnly = true;
		post(payload, (reply, error) ->
		{
			if (error != null || reply == null)
			{
				callback.accept(null, error != null ? error : "Unexpected reply");
			}
			else
			{
				callback.accept(reply.teams == null ? java.util.Collections.emptyList() : reply.teams, null);
			}
		});
	}

	private void post(StorePayload body, BiConsumer<StorePayload, String> callback)
	{
		post(body, true, callback);
	}

	void setMemberKey(String key)
	{
		memberKey = key;
	}

	private void post(StorePayload body, boolean requireEnabled, BiConsumer<StorePayload, String> callback)
	{
		body.memberKey = memberKey;
		HttpUrl url = HttpUrl.parse(config.teamSyncUrl().trim());
		if ((requireEnabled && !config.teamStoreEnabled()) || url == null)
		{
			// Always answer: callers track in-flight state and would otherwise wait forever
			// (e.g. the store was toggled off between their check and this call).
			callback.accept(null, "Store not configured");
			return;
		}
		Request request = new Request.Builder()
			.url(url)
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();
		client().newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Team store request failed", e);
				// A timeout is the store being slow or busy, not gone; say so.
				callback.accept(null, e instanceof java.net.SocketTimeoutException
					|| (e instanceof java.io.InterruptedIOException && "timeout".equals(e.getMessage()))
					? "Timed out" : "Unreachable");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				String body = null;
				try (ResponseBody responseBody = response.body())
				{
					if (!response.isSuccessful() || responseBody == null)
					{
						log.debug("Team store returned {}", response.code());
						callback.accept(null, "HTTP " + response.code());
						return;
					}
					body = responseBody.string();
					callback.accept(gson.fromJson(body, StorePayload.class), null);
				}
				catch (JsonSyntaxException e)
				{
					// A wrong URL (or a proxy in the way) answers with an HTML page,
					// which never parses as JSON.
					log.debug("Team store reply was not JSON: {}", body, e);
					callback.accept(null, "Error page - see the log");
				}
				catch (IOException e)
				{
					log.debug("Could not read team store reply", e);
					callback.accept(null, "Reply cut off");
				}
			}
		});
	}
}

package com.ironspubbingo;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * One tile on the bingo board, deserialized from the board JSON.
 */
public class BingoTile
{
	/** Short label shown on the board, e.g. "5x Ancient Pages from Mith Drags". */
	String label;
	/** Optional longer rules text shown in the tile detail view. */
	String description;
	/** "ALL" (default) = every goal must complete; "ANY" = one goal is enough (for "X or Y" tiles). */
	String mode;
	/** Optional tile icon: an item ID (number) or an exact item name (string, tradeables only). */
	Object icon;
	/** Optional points awarded for completing this tile. */
	Integer points;
	List<BingoGoal> goals;

	transient boolean anyMode;
	/** Item ID given directly in the board file, or -1. */
	transient int iconItemId = -1;
	/** Item name still to be resolved to an ID at render time, or null. */
	transient String iconName;
	/** Cached result of resolving {@link #iconName}: 0 = not tried, -1 = not found. */
	transient int resolvedIconId;

	String validate(int tileIndex)
	{
		String where = "tile " + (tileIndex + 1);
		if (label == null || label.trim().isEmpty())
		{
			return where + ": missing label";
		}
		if (mode != null)
		{
			String m = mode.trim().toUpperCase(Locale.ROOT);
			if (!m.equals("ALL") && !m.equals("ANY"))
			{
				return where + ": mode must be ALL or ANY";
			}
			anyMode = m.equals("ANY");
		}
		if (points != null && points < 0)
		{
			return where + ": points must not be negative";
		}
		if (icon instanceof Number)
		{
			iconItemId = ((Number) icon).intValue();
		}
		else if (icon instanceof String)
		{
			String s = ((String) icon).trim();
			if (!s.isEmpty())
			{
				try
				{
					iconItemId = Integer.parseInt(s);
				}
				catch (NumberFormatException e)
				{
					iconName = s;
				}
			}
		}
		if (goals == null || goals.isEmpty())
		{
			// A tile without goals is a manual tile.
			goals = new ArrayList<>();
			BingoGoal manual = new BingoGoal();
			manual.type = "MANUAL";
			goals.add(manual);
		}
		for (int g = 0; g < goals.size(); g++)
		{
			BingoGoal goal = goals.get(g);
			if (goal == null)
			{
				return where + ", goal " + (g + 1) + ": empty goal";
			}
			String err = goal.validate();
			if (err != null)
			{
				return where + " (\"" + label + "\"), goal " + (g + 1) + ": " + err;
			}
		}
		return null;
	}

	int pointsValue()
	{
		return points == null || points < 0 ? 0 : points;
	}

	/** What this tile TRACKS - goal signatures in order. Labels and points don't count. */
	String trackingSignature()
	{
		StringBuilder sig = new StringBuilder();
		for (BingoGoal goal : goals)
		{
			sig.append(sig.length() > 0 ? ";" : "").append(goal.trackingSignature());
		}
		return sig.toString();
	}

	boolean isComplete(TileProgress progress)
	{
		if (progress.manual)
		{
			return true;
		}
		boolean sawManual = false;
		for (int i = 0; i < goals.size(); i++)
		{
			BingoGoal goal = goals.get(i);
			if (goal.goalType == GoalType.MANUAL)
			{
				sawManual = true;
				continue;
			}
			boolean done = goal.isComplete(progress.goal(i, goals.size()));
			if (anyMode && done)
			{
				return true;
			}
			if (!anyMode && !done)
			{
				return false;
			}
		}
		// ALL mode: complete unless a MANUAL goal is present (those require the manual tick).
		// ANY mode: nothing matched.
		return !anyMode && !sawManual;
	}
}

package com.ironspubbingo;

import java.awt.BasicStroke;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;

/**
 * One tile on the board grid, hand-painted: a rounded card whose color tells its state,
 * an optional bottom-up progress fill, an outline in the Line color on tiles in a
 * completed line (Highlight style), and a white outline on the selected tile.
 */
class BingoTileCell extends JPanel
{
	private static final Color EMPTY_TOP = new Color(44, 44, 44);
	private static final Color EMPTY_BOTTOM = new Color(34, 34, 34);
	private static final Color COMPLETE_TOP = new Color(66, 132, 58);
	private static final Color COMPLETE_BOTTOM = new Color(45, 98, 40);
	private static final Color PARTIAL_TOP = new Color(150, 112, 26);
	private static final Color PARTIAL_BOTTOM = new Color(120, 88, 18);
	private static final Color EDGE = new Color(62, 62, 62);
	private static final Color EDGE_HOVER = new Color(110, 110, 110);

	private boolean complete;
	private boolean partial;
	private float fillFraction;
	private boolean selected;
	private boolean inLine;
	private Color lineColor = BingoUi.COLOR_LINE;
	private boolean hovered;

	BingoTileCell()
	{
		super(new BorderLayout());
		setOpaque(false);
		trackHover(this);
	}

	/**
	 * Sets everything the cell shows in one go. partial colors the whole tile amber (the
	 * classic look); a fill fraction above zero paints amber up from the bottom instead.
	 */
	void setState(boolean complete, boolean partial, float fillFraction, boolean selected, boolean inLine,
		Color lineColor)
	{
		if (this.complete != complete || this.partial != partial || this.fillFraction != fillFraction
			|| this.selected != selected || this.inLine != inLine || !this.lineColor.equals(lineColor))
		{
			this.lineColor = lineColor;
			this.complete = complete;
			this.partial = partial;
			this.fillFraction = fillFraction;
			this.selected = selected;
			this.inLine = inLine;
			repaint();
		}
	}

	/** Child components cover the cell; they report hover too, so the outline follows the mouse. */
	void trackHover(Component component)
	{
		component.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				setHovered(true);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Moving onto a child fires an exit on the parent first; only a real exit counts.
				setHovered(getMousePosition(true) != null);
			}
		});
	}

	private void setHovered(boolean hovered)
	{
		if (this.hovered != hovered)
		{
			this.hovered = hovered;
			repaint();
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int w = getWidth();
		int h = getHeight();
		float arc = Math.max(6f, Math.min(w, h) / 7f);
		Shape card = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1f, h - 1f, arc, arc);

		Color top = complete ? COMPLETE_TOP : partial ? PARTIAL_TOP : EMPTY_TOP;
		Color bottom = complete ? COMPLETE_BOTTOM : partial ? PARTIAL_BOTTOM : EMPTY_BOTTOM;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(card);

		if (!complete && fillFraction > 0f)
		{
			int fillHeight = Math.round(h * Math.min(1f, fillFraction));
			Graphics2D fill = (Graphics2D) g.create();
			fill.clip(card);
			fill.setPaint(new GradientPaint(0, h - fillHeight, PARTIAL_TOP, 0, h, PARTIAL_BOTTOM));
			fill.fillRect(0, h - fillHeight, w, fillHeight);
			fill.dispose();
		}

		float stroke = selected || inLine ? 2f : 1f;
		g.setStroke(new BasicStroke(stroke));
		g.setColor(selected ? Color.WHITE : inLine ? lineColor : hovered ? EDGE_HOVER
			: complete ? COMPLETE_TOP.brighter() : EDGE);
		float inset = stroke / 2f + 0.5f;
		g.draw(new RoundRectangle2D.Float(inset, inset, w - 2 * inset, h - 2 * inset, arc, arc));
		g.dispose();
	}
}

package com.ironspubbingo;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.ProgressBar;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * The tile detail view: title, goals with progress bars, per-member bars, and the
 * Details/Actions foldouts. One instance lives in the sidebar panel and another under
 * the pop-out board, so both surfaces show the same thing and stay in sync.
 */
class BingoTileDetail extends JPanel
{
	/** Name suffix the team store puts on admin-credited members. */
	private static final String VERIFIED_SUFFIX = " (verified)";

	private final IronsPubBingoPlugin plugin;
	private final int widthBasis;

	private int selectedTile = -1;
	private boolean detailsExpanded;
	private boolean actionsExpanded;
	/** Goals whose contributor rows are unfolded (click the goal's bar to toggle). */
	private final java.util.Set<Integer> expandedGoals = new java.util.HashSet<>();
	/** The board the expanded goals belong to; another board starts folded. */
	private BingoBoard expandedBoard;
	/** A credit request is on its way to the store; the button says so meanwhile. */
	private boolean requestInFlight;

	BingoTileDetail(IronsPubBingoPlugin plugin, int widthBasis)
	{
		this.plugin = plugin;
		this.widthBasis = widthBasis;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setAlignmentX(LEFT_ALIGNMENT);
	}

	void setSelectedTile(int tileIndex)
	{
		if (tileIndex != selectedTile)
		{
			expandedGoals.clear();
		}
		selectedTile = tileIndex;
	}

	/**
	 * Rebuilds the view for the current selection.
	 *
	 * @return whether there is a tile to show (drives the surrounding card's visibility)
	 */
	boolean rebuild()
	{
		removeAll();
		BingoBoard board = plugin.getBoard();
		if (board != expandedBoard)
		{
			expandedGoals.clear();
			expandedBoard = board;
		}
		boolean show = board != null && selectedTile >= 0 && selectedTile < board.getTiles().size();
		setVisible(show);
		if (!show)
		{
			return false;
		}

		BingoTile tile = board.getTiles().get(selectedTile);
		// Merged progress is live, a completed tile included.
		TileProgress merged = plugin.mergedProgressFor(selectedTile);
		TileProgress own = plugin.progressFor(selectedTile);
		boolean teamView = plugin.hasTeamData();
		Map<String, TileProgress> members = teamView ? plugin.memberProgressFor(selectedTile) : null;

		BingoWrappedLabel titleLabel = new BingoWrappedLabel(
			(plugin.showTileNumbers() ? (selectedTile + 1) + ". " : "") + tile.label, widthBasis - 44);
		titleLabel.setFont(FontManager.getRunescapeBoldFont());
		titleLabel.setForeground(Color.WHITE);
		AsyncBufferedImage itemIcon = plugin.iconFor(tile);
		if (itemIcon == null)
		{
			add(titleLabel);
		}
		else
		{
			// Fixed wrap width beside the icon: deriving it from the layout would measure
			// once before and once after the icon's width is known, and a title sitting on
			// a wrap boundary would visibly twitch between one and two lines.
			JLabel iconLabel = new JLabel();
			BingoUi.applyIcon(iconLabel, itemIcon, 32, this);
			titleLabel.setWrapWidth(widthBasis - 44);
			JPanel titleRow = new JPanel(new java.awt.BorderLayout(8, 0));
			titleRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			titleRow.setAlignmentX(LEFT_ALIGNMENT);
			titleRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));
			titleRow.add(iconLabel, java.awt.BorderLayout.WEST);
			titleRow.add(titleLabel, java.awt.BorderLayout.CENTER);
			add(titleRow);
		}

		if (tile.pointsValue() > 0 || tile.goals.size() > 1)
		{
			StringBuilder meta = new StringBuilder();
			if (tile.pointsValue() > 0)
			{
				meta.append(tile.pointsValue()).append(" pts");
			}
			if (tile.goals.size() > 1)
			{
				if (meta.length() > 0)
				{
					meta.append("  ·  ");
				}
				meta.append(tile.anyMode ? "Complete ANY goal" : "Complete ALL goals");
			}
			BingoWrappedLabel metaLabel = new BingoWrappedLabel(meta.toString(), widthBasis);
			metaLabel.setForeground(ColorScheme.BRAND_ORANGE);
			add(Box.createVerticalStrut(2));
			add(metaLabel);
		}

		if (tile.description != null && !tile.description.trim().isEmpty())
		{
			BingoWrappedLabel desc = new BingoWrappedLabel(tile.description.trim(), widthBasis);
			add(Box.createVerticalStrut(4));
			add(desc);
		}

		// A manual tick overrides the bars visually; the tracked numbers underneath are
		// untouched, so unticking shows the real progress again.
		boolean ticked = merged.manual;

		add(Box.createVerticalStrut(6));
		for (int g = 0; g < tile.goals.size(); g++)
		{
			BingoGoal goal = tile.goals.get(g);
			GoalProgress p = merged.goal(g, tile.goals.size());
			boolean done = ticked || goal.isComplete(p);
			if (g > 0)
			{
				add(Box.createVerticalStrut(6));
			}

			BingoWrappedLabel goalLabel = new BingoWrappedLabel(plugin.goalLabel(goal), widthBasis);
			goalLabel.setForeground(done ? BingoUi.COLOR_GOAL_DONE : ColorScheme.LIGHT_GRAY_COLOR);
			if (plugin.goalHasExtraDetail(goal))
			{
				goalLabel.setToolTipText(plugin.goalDescription(goal));
			}
			add(goalLabel);

			if (goal.goalType == GoalType.MANUAL)
			{
				ProgressBar manualBar = progressBar(ticked ? 1 : 0, 1, 18);
				manualBar.setCenterLabel(ticked ? "1 / 1" : "0 / 1");
				add(manualBar);
				continue;
			}

			long target = goal.target();
			// A goal's number never shows past its target, nor below zero (negative credit).
			long tracked = Math.max(0, Math.min(goal.progressOf(p), target));
			long value = ticked ? target : tracked;
			// Keep the real numbers visible on an overridden bar.
			String centerLabel = ticked && tracked < target
				? "Ticked  (" + formatCount(tracked) + " / " + formatCount(target) + ")"
				: formatCount(value) + " / " + formatCount(target);

			// Who contributed what, largest share first. The goal bar is painted in one
			// segment per contributor and unfolds their rows when clicked, so the
			// contributions live on the bar itself instead of behind a separate toggle.
			List<MemberBar> bars = new ArrayList<>();
			List<GoalBar.Segment> segments = new ArrayList<>();
			if (teamView)
			{
				final int goalIndex = g;
				final int goalCount = tile.goals.size();
				List<Map.Entry<String, TileProgress>> ordered = new ArrayList<>(members.entrySet());
				ordered.sort((a, b) -> Long.compare(
					goal.progressOf(b.getValue().goal(goalIndex, goalCount)),
					goal.progressOf(a.getValue().goal(goalIndex, goalCount))));
				for (Map.Entry<String, TileProgress> entry : ordered)
				{
					long share = goal.progressOf(entry.getValue().goal(goalIndex, goalCount));
					if (share <= 0)
					{
						continue;
					}
					String memberName = entry.getKey();
					boolean verified = memberName.endsWith(VERIFIED_SUFFIX);
					if (verified)
					{
						// The "(verified)" suffix would eat the name's space - a
						// checkmark says the same thing.
						memberName = memberName.substring(0,
							memberName.length() - VERIFIED_SUFFIX.length()) + verifiedMark();
					}
					segments.add(new GoalBar.Segment(memberName, share));
					// Hand-painted: RuneLite's ProgressBar gives its left label only a
					// third of the width, truncating names long before space runs out.
					MemberBar memberBar = new MemberBar(memberName, formatCount(share),
						Math.min(1f, share / (float) target), widthBasis);
					if (verified)
					{
						memberBar.setToolTipText("Credited by an admin");
					}
					bars.add(memberBar);
				}
			}
			final int goalIdx = g;
			boolean expanded = expandedGoals.contains(goalIdx);
			GoalBar bar = new GoalBar(value, target, centerLabel, ticked ? new ArrayList<>() : segments,
				bars.isEmpty() ? null : expanded, widthBasis);
			bar.setToolTipText(barTooltip(goal, segments));
			if (!bars.isEmpty())
			{
				bar.addMouseListener(new java.awt.event.MouseAdapter()
				{
					@Override
					public void mouseClicked(java.awt.event.MouseEvent e)
					{
						if (!expandedGoals.remove(goalIdx))
						{
							expandedGoals.add(goalIdx);
						}
						rebuild();
						revalidate();
						repaint();
					}
				});
			}
			add(bar);
			if (expanded)
			{
				for (MemberBar memberRow : bars)
				{
					add(Box.createVerticalStrut(2));
					add(memberRow);
				}
			}
		}

		// Who ticked the tile sits right under the bars, before any foldouts.
		if (teamView && merged.manual)
		{
			StringBuilder tickedBy = new StringBuilder();
			for (Map.Entry<String, TileProgress> entry : members.entrySet())
			{
				if (entry.getValue().manual)
				{
					if (tickedBy.length() > 0)
					{
						tickedBy.append(", ");
					}
					tickedBy.append(entry.getKey());
				}
			}
			BingoWrappedLabel tickedByLabel = new BingoWrappedLabel("Ticked off by: " + tickedBy, widthBasis);
			add(Box.createVerticalStrut(2));
			add(tickedByLabel);
		}

		// Long item and source lists live behind a toggle - but only when the goal labels
		// don't already say everything, so simple tiles stay clutter-free.
		// Each entry is {full goal description or null, received items or null}.
		List<String[]> extraInfo = new ArrayList<>();
		for (int g = 0; g < tile.goals.size(); g++)
		{
			BingoGoal goal = tile.goals.get(g);
			GoalProgress p = merged.goal(g, tile.goals.size());
			String description = plugin.goalHasExtraDetail(goal) ? plugin.goalDescription(goal) : null;
			String received = null;
			if (goal.usesMatchedSet() && p.matched != null && !p.matched.isEmpty())
			{
				received = "Received: " + String.join(", ", sortedNames(p.matched));
			}
			else if (p.got != null && !p.got.isEmpty())
			{
				// Counted drops: "Uncut onyx x2, Zulrah's scales x300", biggest first.
				List<Map.Entry<String, Long>> entries = new ArrayList<>(p.got.entrySet());
				entries.sort((a, b) -> Long.compare(b.getValue(), a.getValue()));
				StringBuilder list = new StringBuilder("Received: ");
				for (int i = 0; i < entries.size(); i++)
				{
					list.append(i > 0 ? ", " : "").append(entries.get(i).getKey());
					if (entries.get(i).getValue() > 1)
					{
						list.append(" x").append(formatCount(entries.get(i).getValue()));
					}
				}
				received = list.toString();
			}
			if (description != null || received != null)
			{
				extraInfo.add(new String[]{description, received});
			}
		}

		if (!extraInfo.isEmpty())
		{
			add(Box.createVerticalStrut(6));
			JButton detailsToggle = smallButton(detailsExpanded ? "Details  ▾" : "Details  ▸");
			detailsToggle.setHorizontalAlignment(SwingConstants.LEFT);
			detailsToggle.addActionListener(e ->
			{
				detailsExpanded = !detailsExpanded;
				rebuild();
				revalidate();
				repaint();
			});
			add(detailsToggle);

			if (detailsExpanded)
			{
				for (int i = 0; i < extraInfo.size(); i++)
				{
					String[] info = extraInfo.get(i);
					int topGap = i == 0 ? 4 : 6;
					if (info[0] != null)
					{
						BingoWrappedLabel infoLabel = new BingoWrappedLabel(info[0], widthBasis - 8);
						infoLabel.setBorder(BorderFactory.createEmptyBorder(topGap, 8, 0, 0));
						add(infoLabel);
						topGap = 0;
					}
					if (info[1] != null)
					{
						BingoWrappedLabel receivedLabel = new BingoWrappedLabel(info[1], widthBasis - 8);
						receivedLabel.setForeground(BingoUi.COLOR_GOAL_DONE);
						receivedLabel.setBorder(BorderFactory.createEmptyBorder(topGap, 8, 0, 0));
						add(receivedLabel);
					}
				}
			}
		}

		add(Box.createVerticalStrut(6));

		// On a store team every completion claim goes through an admin, so the manual
		// tick disappears entirely - a self-serve tick would bypass the review the
		// Requests tab exists for. Party-only teams keep it (there is no reviewer).
		final int tileIndex = selectedTile;
		final boolean ownTicked = own.manual;
		JButton tick = null;
		if (!plugin.storeConfigured())
		{
			tick = smallButton(ownTicked ? "Remove manual tick" : "Tick off tile (manual)");
			tick.setToolTipText(ownTicked
				? "Remove your tick for the whole team"
				: "Mark this tile complete by hand");
			tick.addActionListener(e -> plugin.setManualComplete(tileIndex, !ownTicked));
		}

		JButton request = smallButton(requestInFlight ? "Sending request..." : "Request admin credit");
		request.setEnabled(plugin.storeConfigured() && !requestInFlight);
		request.addActionListener(e -> requestCredit(tileIndex, tile));

		JButton reset = smallButton("Reset tile progress");
		reset.addActionListener(e ->
		{
			int answer = JOptionPane.showConfirmDialog(this,
				"Reset all tracked progress on this tile?", "Irons Pub Bingo", JOptionPane.YES_NO_OPTION);
			if (answer == JOptionPane.YES_OPTION)
			{
				plugin.resetTileProgress(tileIndex);
			}
		});

		// All tile actions behind one foldout; its state survives the constant detail
		// rebuilds via the actionsExpanded field.
		JButton actionsToggle = smallButton("Actions  " + (actionsExpanded ? "▾" : "▸"));
		actionsToggle.setHorizontalAlignment(SwingConstants.LEFT);
		JPanel actionsCard = new JPanel();
		actionsCard.setLayout(new BoxLayout(actionsCard, BoxLayout.Y_AXIS));
		actionsCard.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		actionsCard.setAlignmentX(LEFT_ALIGNMENT);
		if (tick != null)
		{
			actionsCard.add(tick);
			actionsCard.add(Box.createVerticalStrut(4));
		}
		actionsCard.add(request);
		actionsCard.add(Box.createVerticalStrut(4));
		actionsCard.add(reset);
		actionsCard.setVisible(actionsExpanded);
		actionsToggle.addActionListener(e ->
		{
			actionsExpanded = !actionsCard.isVisible();
			actionsCard.setVisible(actionsExpanded);
			actionsToggle.setText("Actions  " + (actionsExpanded ? "▾" : "▸"));
			revalidate();
			repaint();
		});
		add(actionsToggle);
		add(Box.createVerticalStrut(4));
		add(actionsCard);
		return true;
	}

	/** Dialog for a credit request: amount or completion, plus a note for the admin. */
	private void requestCredit(int tileIndex, BingoTile tile)
	{
		JPanel form = new JPanel(new GridLayout(0, 1, 0, 4));
		JComboBox<String> goalBox = null;
		// Each goal with where the team stands, so the player sees what the amount adds to.
		TileProgress current = plugin.mergedProgressFor(tileIndex);
		String[] labels = new String[tile.goals.size()];
		for (int g = 0; g < tile.goals.size(); g++)
		{
			BingoGoal goal = tile.goals.get(g);
			labels[g] = (tile.goals.size() > 1 ? (g + 1) + ". " : "") + plugin.goalLabel(goal)
				+ (goal.goalType == GoalType.MANUAL ? ""
					: "  (" + formatCount(goal.progressOf(current.goal(g, tile.goals.size())))
						+ " / " + formatCount(goal.target()) + ")");
		}
		if (tile.goals.size() > 1)
		{
			goalBox = new JComboBox<>(labels);
			form.add(new JLabel("Goal:"));
			form.add(goalBox);
		}
		else if (labels.length == 1)
		{
			form.add(new JLabel("Goal: " + labels[0]));
		}
		JTextField amount = new JTextField();
		JCheckBox complete = new JCheckBox("Mark the whole tile complete instead");
		JTextField note = new JTextField();
		JTextField links = new JTextField();
		JCheckBox proofShot = new JCheckBox("Attach a screenshot (posts to your Discord webhook)");
		proofShot.setEnabled(plugin.webhookConfigured());
		// Proof is what the admin asks for first. Attach it by default only when the
		// player already posts completions to the webhook.
		proofShot.setSelected(plugin.webhookConfigured() && plugin.postCompletions());
		complete.addActionListener(e -> amount.setEnabled(!complete.isSelected()));
		proofShot.setToolTipText(plugin.webhookConfigured()
			? "Screenshots the game, posts it to your Discord webhook and files its link as proof"
			: "Set a Discord webhook in the settings first");
		form.add(new JLabel("Amount to credit (e.g. 40):"));
		form.add(amount);
		form.add(complete);
		form.add(new JLabel("Note for the admin (e.g. laps 0 to 40):"));
		form.add(note);
		form.add(new JLabel("Proof links (Discord or Imgur screenshots):"));
		form.add(links);
		form.add(proofShot);

		int answer = JOptionPane.showConfirmDialog(this, form,
			"Request admin credit - " + tile.label, JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
		if (answer != JOptionPane.OK_OPTION)
		{
			return;
		}
		Long add = null;
		String amountText = complete.isSelected() ? "" : amount.getText().trim();
		if (!amountText.isEmpty())
		{
			try
			{
				add = Long.parseLong(amountText);
			}
			catch (NumberFormatException e)
			{
				add = -1L;
			}
			if (add <= 0)
			{
				JOptionPane.showMessageDialog(this, "Amount must be a whole number above 0.",
					"Irons Pub Bingo", JOptionPane.WARNING_MESSAGE);
				return;
			}
		}
		if (add == null && !complete.isSelected())
		{
			JOptionPane.showMessageDialog(this,
				"Fill in an amount, or tick \"mark the whole tile complete\".",
				"Irons Pub Bingo", JOptionPane.WARNING_MESSAGE);
			return;
		}
		Integer goalIndex = goalBox == null ? null : goalBox.getSelectedIndex();
		requestInFlight = true;
		rebuild();
		revalidate();
		repaint();
		final Long addFinal = add;
		final String noteText = note.getText().trim();
		final String manualLinks = links.getText().trim();
		if (proofShot.isSelected())
		{
			// Screenshot first, so its Discord link rides along as a proof link. A failed
			// screenshot never blocks the request itself.
			String what = complete.isSelected() ? "tile complete" : "+" + addFinal;
			String goalPart = goalIndex == null ? ""
				: " on goal " + (goalIndex + 1) + " (" + plugin.goalLabel(tile.goals.get(goalIndex)) + ")";
			String detail = tile.label + " (" + what + goalPart + ")";
			plugin.postProofScreenshot(detail, (link, shotError) -> SwingUtilities.invokeLater(() ->
				sendRequest(tileIndex, goalIndex, addFinal, complete.isSelected(), noteText,
					link == null ? manualLinks : manualLinks.isEmpty() ? link : manualLinks + " " + link,
					shotError)));
		}
		else
		{
			sendRequest(tileIndex, goalIndex, addFinal, complete.isSelected(), noteText, manualLinks, null);
		}
	}

	private void sendRequest(int tileIndex, Integer goalIndex, Long add, boolean complete,
		String note, String links, String screenshotError)
	{
		plugin.submitCreditRequest(tileIndex, goalIndex, add, complete, note, links,
			(ok, error) -> SwingUtilities.invokeLater(() ->
			{
				requestInFlight = false;
				rebuild();
				revalidate();
				repaint();
				String message = ok ? "Request sent. A team admin will review it."
					: "Could not send the request: " + error;
				if (ok && screenshotError != null)
				{
					message += "\nThe screenshot didn't attach (" + screenshotError
						+ "). Add a proof link yourself if the admin needs one.";
				}
				JOptionPane.showMessageDialog(this, message, "Irons Pub Bingo",
					ok && screenshotError == null ? JOptionPane.INFORMATION_MESSAGE : JOptionPane.WARNING_MESSAGE);
			}));
	}

	/**
	 * A thin per-member bar: fill fraction behind, name left, count right. The name gets
	 * every pixel the count doesn't need (clipped with ".." only when truly out of room).
	 */
	private static class MemberBar extends JPanel
	{
		private final String name;
		private final String count;
		private final float fraction;

		MemberBar(String name, String count, float fraction, int widthBasis)
		{
			this.name = name;
			this.count = count;
			this.fraction = fraction;
			setPreferredSize(new Dimension(widthBasis, 14));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 14));
			setMinimumSize(new Dimension(40, 14));
			setAlignmentX(LEFT_ALIGNMENT);
			setFont(FontManager.getRunescapeSmallFont());
		}

		@Override
		protected void paintComponent(java.awt.Graphics g)
		{
			super.paintComponent(g);
			int w = getWidth();
			int h = getHeight();
			g.setColor(ColorScheme.DARK_GRAY_COLOR);
			g.fillRect(0, 0, w, h);
			g.setColor(fraction >= 1f ? BingoUi.COLOR_COMPLETE : BingoUi.COLOR_PARTIAL);
			g.fillRect(0, 0, Math.round(w * Math.max(0f, Math.min(1f, fraction))), h);

			java.awt.FontMetrics metrics = g.getFontMetrics(getFont());
			int baseline = (h + metrics.getAscent() - metrics.getDescent()) / 2;
			int countWidth = metrics.stringWidth(count);
			String shownName = name;
			int available = w - countWidth - 12;
			if (metrics.stringWidth(shownName) > available)
			{
				while (shownName.length() > 1
					&& metrics.stringWidth(shownName + "..") > available)
				{
					shownName = shownName.substring(0, shownName.length() - 1);
				}
				shownName += "..";
			}
			g.setFont(getFont());
			g.setColor(Color.BLACK);
			g.drawString(shownName, 5, baseline + 1);
			g.drawString(count, w - countWidth - 3, baseline + 1);
			g.setColor(Color.WHITE);
			g.drawString(shownName, 4, baseline);
			g.drawString(count, w - countWidth - 4, baseline);
		}
	}

	/** Tooltip for a goal bar: the full goal text (when it says more) and the contributors. */
	private String barTooltip(BingoGoal goal, List<GoalBar.Segment> segments)
	{
		StringBuilder tip = new StringBuilder("<html>");
		if (plugin.goalHasExtraDetail(goal))
		{
			tip.append(plugin.goalDescription(goal));
		}
		if (!segments.isEmpty())
		{
			tip.append(tip.length() > 6 ? "<br>" : "").append("Click to show or hide contributors");
			for (GoalBar.Segment segment : segments)
			{
				tip.append("<br>").append(segment.name).append(": ").append(formatCount(segment.amount));
			}
		}
		return tip.length() > 6 ? tip.append("</html>").toString() : null;
	}

	/**
	 * A goal's progress bar, painted in one segment per contributor (alternating shades,
	 * largest first) with the count centered and, when it can unfold contributor rows,
	 * a small arrow on the right.
	 */
	private static class GoalBar extends JPanel
	{
		static class Segment
		{
			final String name;
			final long amount;

			Segment(String name, long amount)
			{
				this.name = name;
				this.amount = amount;
			}
		}

		private final long value;
		private final long target;
		private final String label;
		private final List<Segment> segments;
		/** null: nothing to unfold; otherwise whether the rows are currently shown. */
		private final Boolean expanded;

		GoalBar(long value, long target, String label, List<Segment> segments, Boolean expanded, int widthBasis)
		{
			this.value = value;
			this.target = Math.max(1, target);
			this.label = label;
			this.segments = segments;
			this.expanded = expanded;
			setPreferredSize(new Dimension(widthBasis, 18));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
			setMinimumSize(new Dimension(40, 18));
			setAlignmentX(LEFT_ALIGNMENT);
			setFont(FontManager.getRunescapeSmallFont());
			if (expanded != null)
			{
				setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
			}
		}

		@Override
		protected void paintComponent(java.awt.Graphics g)
		{
			super.paintComponent(g);
			int w = getWidth();
			int h = getHeight();
			g.setColor(ColorScheme.DARK_GRAY_COLOR);
			g.fillRect(0, 0, w, h);
			Color base = value >= target ? BingoUi.COLOR_COMPLETE : BingoUi.COLOR_PARTIAL;
			if (segments.isEmpty())
			{
				g.setColor(base);
				g.fillRect(0, 0, Math.round(w * Math.min(1f, value / (float) target)), h);
			}
			else
			{
				// Segments in proportion to the target; past it, the bar is simply full.
				int x = 0;
				long shown = 0;
				for (int i = 0; i < segments.size() && shown < target; i++)
				{
					long amount = Math.min(segments.get(i).amount, target - shown);
					shown += amount;
					int end = Math.round(w * Math.min(1f, shown / (float) target));
					g.setColor(i % 2 == 0 ? base : base.darker());
					g.fillRect(x, 0, end - x, h);
					x = end;
				}
			}

			java.awt.FontMetrics metrics = g.getFontMetrics(getFont());
			int baseline = (h + metrics.getAscent() - metrics.getDescent()) / 2;
			int textX = (w - metrics.stringWidth(label)) / 2;
			g.setFont(getFont());
			g.setColor(Color.BLACK);
			g.drawString(label, textX + 1, baseline + 1);
			g.setColor(Color.WHITE);
			g.drawString(label, textX, baseline);
			if (expanded != null)
			{
				String arrow = expanded ? "▾" : "▸";
				int arrowX = w - metrics.stringWidth(arrow) - 4;
				g.setColor(Color.BLACK);
				g.drawString(arrow, arrowX + 1, baseline + 1);
				g.setColor(Color.WHITE);
				g.drawString(arrow, arrowX, baseline);
			}
		}
	}

	/** Compact verified marker, falling back to text if the font lacks the checkmark glyph. */
	private static String verifiedMark()
	{
		return FontManager.getRunescapeSmallFont().canDisplay('✔') ? " ✔" : " (v)";
	}

	/** A progress bar styled for the panel: complete bars go green, partial ones amber. */
	private ProgressBar progressBar(long value, long target, int height)
	{
		ProgressBar bar = new ProgressBar();
		bar.setMaximumValue((int) Math.max(1, Math.min(Integer.MAX_VALUE, target)));
		bar.setValue((int) Math.max(0, Math.min(Integer.MAX_VALUE, value)));
		bar.setForeground(value >= target ? BingoUi.COLOR_COMPLETE : BingoUi.COLOR_PARTIAL);
		bar.setBackground(ColorScheme.DARK_GRAY_COLOR);
		bar.setFont(FontManager.getRunescapeSmallFont());
		bar.setPreferredSize(new Dimension(widthBasis, height));
		bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		bar.setMinimumSize(new Dimension(40, height));
		bar.setAlignmentX(LEFT_ALIGNMENT);
		return bar;
	}

	/** Received item names, alphabetical and case-insensitive, for stable display. */
	private static List<String> sortedNames(java.util.Collection<String> names)
	{
		List<String> sorted = new ArrayList<>(names);
		sorted.sort(String.CASE_INSENSITIVE_ORDER);
		return sorted;
	}

	/** Compact counts so bar labels stay inside the bar: 15000 -> 15k, 5000000 -> 5M. */
	private static String formatCount(long value)
	{
		if (value >= 1_000_000)
		{
			double millions = value / 1_000_000d;
			return (millions == Math.floor(millions) ? String.valueOf((long) millions)
				: String.format("%.1f", millions)) + "M";
		}
		if (value >= 10_000)
		{
			return (value / 1000) + "k";
		}
		return String.valueOf(value);
	}

	private static JButton smallButton(String text)
	{
		JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setAlignmentX(LEFT_ALIGNMENT);
		button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		button.setFocusable(false);
		return button;
	}
}

package com.ironspubbingo;

import java.awt.Color;
import java.awt.Image;
import javax.swing.ImageIcon;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Shared look and rendering helpers for the sidebar panel and the pop-out board window.
 */
final class BingoUi
{
	static final Color COLOR_COMPLETE = new Color(60, 124, 50);
	static final Color COLOR_PARTIAL = new Color(148, 111, 22);
	/** Gold, as on the clan logo: the pop-out header rule and the line count chip. */
	static final Color COLOR_GOLD = new Color(226, 173, 72);
	/** Completed bingo lines, unless the Line color setting says otherwise. */
	static final Color COLOR_LINE = new Color(255, 0, 0);
	static final Color COLOR_GOAL_DONE = new Color(122, 200, 108);
	static final Color COLOR_CHIP = new Color(40, 40, 40);
	static final Color COLOR_CHIP_EDGE = new Color(64, 64, 64);

	private BingoUi()
	{
	}

	/**
	 * A small rounded label for a stat ("12 / 25 tiles"): bold value, quieter caption.
	 * Painted, so it looks the same in the sidebar and the pop-out window.
	 */
	static final class Chip extends JLabel
	{
		Chip()
		{
			setOpaque(false);
			setFont(net.runelite.client.ui.FontManager.getRunescapeSmallFont());
			setBorder(javax.swing.BorderFactory.createEmptyBorder(3, 9, 3, 9));
		}

		/** Updates the chip; a null caption shows the value alone, a null color means white. */
		void set(String value, String caption, Color valueColor)
		{
			String text = "<html><b>" + escapeHtml(value) + "</b>"
				+ (caption == null ? "" : " <font color='#a0a0a0'>" + escapeHtml(caption) + "</font>") + "</html>";
			if (!text.equals(getText()))
			{
				setText(text);
			}
			setForeground(valueColor == null ? Color.WHITE : valueColor);
		}

		@Override
		protected void paintComponent(java.awt.Graphics graphics)
		{
			java.awt.Graphics2D g = (java.awt.Graphics2D) graphics.create();
			g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(COLOR_CHIP);
			g.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, getHeight(), getHeight());
			g.setColor(COLOR_CHIP_EDGE);
			g.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, getHeight(), getHeight());
			g.dispose();
			super.paintComponent(graphics);
		}
	}

	/** 1st, 2nd, 3rd, 4th, 11th, 21st... */
	static String ordinal(int n)
	{
		if (n % 100 >= 11 && n % 100 <= 13)
		{
			return n + "th";
		}
		switch (n % 10)
		{
			case 1:
				return n + "st";
			case 2:
				return n + "nd";
			case 3:
				return n + "rd";
			default:
				return n + "th";
		}
	}

	/** Gold, silver, bronze for the top three placements, white after that. */
	static Color rankColor(int rank)
	{
		return rank == 1 ? new Color(255, 215, 0) : rank == 2 ? new Color(232, 232, 232)
			: rank == 3 ? new Color(215, 141, 74) : Color.WHITE;
	}

	static String escapeHtml(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Sets a (rescaled) item sprite on the label, re-applying once the sprite loads. */
	static void applyIcon(JLabel label, AsyncBufferedImage image, int maxSize, JComponent repaintTarget)
	{
		Runnable apply = () ->
		{
			int w = image.getWidth();
			int h = image.getHeight();
			if (w <= 0 || h <= 0)
			{
				return;
			}
			double scale = Math.min(1.0, (double) maxSize / Math.max(w, h));
			Image scaled = scale < 1.0
				? image.getScaledInstance(Math.max(1, (int) (w * scale)), Math.max(1, (int) (h * scale)), Image.SCALE_SMOOTH)
				: image;
			label.setIcon(new ImageIcon(scaled));
			repaintTarget.revalidate();
			repaintTarget.repaint();
		};
		apply.run();
		image.onLoaded(() -> SwingUtilities.invokeLater(apply));
	}

	/** The right-click menu on a board tile: pin it to the in-game overlay, or unpin it. */
	static void showTileMenu(IronsPubBingoPlugin plugin, int tileIndex, java.awt.event.MouseEvent e)
	{
		javax.swing.JPopupMenu menu = new javax.swing.JPopupMenu();
		javax.swing.JMenuItem pin = new javax.swing.JMenuItem(
			plugin.isTilePinned(tileIndex) ? "Unpin from overlay" : "Pin to overlay");
		pin.addActionListener(a -> plugin.togglePinnedTile(tileIndex));
		menu.add(pin);
		if (!plugin.pinnedTiles().isEmpty())
		{
			javax.swing.JMenuItem unpinAll = new javax.swing.JMenuItem("Unpin all tiles");
			unpinAll.addActionListener(a -> plugin.unpinAllTiles());
			menu.add(unpinAll);
		}
		menu.show(e.getComponent(), e.getX(), e.getY());
	}
}

package com.ironspubbingo;

import java.awt.Color;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Insets;
import java.awt.event.ComponentAdapter;
import java.awt.event.ComponentEvent;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Word-wrapping text component that measures and paints every line itself, wrapping to the
 * width it is actually given. Swing's HTML renderer needs a hard-coded pixel width, which
 * silently clips whenever that guess is wider than the real column, so plugin text uses
 * this instead.
 */
class BingoWrappedLabel extends JComponent
{
	private final int alignment;
	private final int fallbackWidth;
	private int explicitWrapWidth;
	private int lastLineCount = -1;
	private String text;
	private String secondary;
	private Color secondaryColor = ColorScheme.LIGHT_GRAY_COLOR;

	BingoWrappedLabel(String text, int fallbackWidth)
	{
		this(text, SwingConstants.LEFT, fallbackWidth);
	}

	BingoWrappedLabel(String text, int alignment, int fallbackWidth)
	{
		this.text = text == null ? "" : text;
		this.alignment = alignment;
		this.fallbackWidth = fallbackWidth;
		setFont(FontManager.getRunescapeSmallFont());
		setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		setAlignmentX(alignment == SwingConstants.CENTER ? CENTER_ALIGNMENT : LEFT_ALIGNMENT);
		addComponentListener(new ComponentAdapter()
		{
			@Override
			public void componentResized(ComponentEvent e)
			{
				// Height depends on width, so re-layout when the new width wraps into a
				// different number of lines. Comparing line counts (not widths) converges:
				// once the height matches the width, no further revalidate is triggered.
				if (lineCount() != lastLineCount)
				{
					revalidate();
				}
			}
		});
	}

	String getText()
	{
		return text;
	}

	void setText(String text)
	{
		this.text = text == null ? "" : text;
		revalidate();
		repaint();
	}

	/** Optional second block of lines, drawn under the main text in its own color. */
	void setSecondary(String secondary, Color color)
	{
		this.secondary = secondary;
		if (color != null)
		{
			this.secondaryColor = color;
		}
		revalidate();
		repaint();
	}

	/** Forces a wrap width instead of deriving it from the component's own width. */
	void setWrapWidth(int width)
	{
		if (width != explicitWrapWidth)
		{
			explicitWrapWidth = width;
			revalidate();
			repaint();
		}
	}

	private int wrapWidth()
	{
		if (explicitWrapWidth > 0)
		{
			return explicitWrapWidth;
		}
		int width = getWidth();
		if (width <= 0)
		{
			Container parent = getParent();
			if (parent != null && parent.getWidth() > 0)
			{
				Insets parentInsets = parent.getInsets();
				width = parent.getWidth() - parentInsets.left - parentInsets.right;
			}
		}
		if (width <= 0)
		{
			width = fallbackWidth;
		}
		Insets insets = getInsets();
		return Math.max(24, width - insets.left - insets.right);
	}

	/** Wraps to the given width, honoring explicit line breaks in the text. */
	private List<String> wrap(FontMetrics metrics, String value, int width)
	{
		List<String> lines = new ArrayList<>();
		if (value == null || value.isEmpty())
		{
			return lines;
		}
		for (String paragraph : value.split("\n", -1))
		{
			StringBuilder current = new StringBuilder();
			for (String word : paragraph.split(" "))
			{
				if (current.length() == 0)
				{
					current.append(word);
				}
				else if (metrics.stringWidth(current + " " + word) <= width)
				{
					current.append(' ').append(word);
				}
				else
				{
					lines.add(current.toString());
					current = new StringBuilder(word);
				}
				// A single unbreakable run (a URL, a pasted code) wider than the column
				// would otherwise overflow; break it mid-word instead.
				while (metrics.stringWidth(current.toString()) > width && current.length() > 1)
				{
					int fit = current.length() - 1;
					while (fit > 1 && metrics.stringWidth(current.substring(0, fit)) > width)
					{
						fit--;
					}
					lines.add(current.substring(0, fit));
					current = new StringBuilder(current.substring(fit));
				}
			}
			lines.add(current.toString());
		}
		return lines;
	}

	private int lineCount()
	{
		FontMetrics metrics = getFontMetrics(getFont());
		int width = wrapWidth();
		return wrap(metrics, text, width).size() + wrap(metrics, secondary, width).size();
	}

	@Override
	public Dimension getPreferredSize()
	{
		FontMetrics metrics = getFontMetrics(getFont());
		int width = wrapWidth();
		int lines = lineCount();
		lastLineCount = lines;
		Insets insets = getInsets();
		return new Dimension(width + insets.left + insets.right,
			Math.max(1, lines) * metrics.getHeight() + insets.top + insets.bottom);
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		g.setFont(getFont());
		FontMetrics metrics = g.getFontMetrics();
		Insets insets = getInsets();
		int width = wrapWidth();
		List<String> mainLines = wrap(metrics, text, width);
		List<String> secondaryLines = wrap(metrics, secondary, width);
		// Layouts can hand this component more height than the text needs (the tile
		// title stretched to its icon's height): center the text block in the extra.
		int contentHeight = (mainLines.size() + secondaryLines.size()) * metrics.getHeight();
		int y = insets.top + metrics.getAscent()
			+ Math.max(0, (getHeight() - insets.top - insets.bottom - contentHeight) / 2);

		g.setColor(getForeground());
		y = paintLines(g, metrics, mainLines, width, insets.left, y);
		if (secondary != null)
		{
			g.setColor(secondaryColor);
			paintLines(g, metrics, secondaryLines, width, insets.left, y);
		}
	}

	private int paintLines(Graphics g, FontMetrics metrics, List<String> lines, int width, int left, int y)
	{
		for (String line : lines)
		{
			int x = alignment == SwingConstants.CENTER
				? left + (width - metrics.stringWidth(line)) / 2
				: left;
			g.drawString(line, x, y);
			y += metrics.getHeight();
		}
		return y;
	}
}

package com.ironspubbingo;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * Saved progress for one goal. Serialized to profile config as part of {@link TileProgress}.
 */
public class GoalProgress
{
	/** Generic counter: drops received, purples, kills, pets, chat matches, or XP gained. */
	long n;
	/** Distinct item names received (lowercase), for distinct DROP goals. */
	Set<String> matched;
	/**
	 * Item name -> quantity received, for counted (non-distinct) DROP goals, so the tile
	 * can say what the number is made of. Capped; a goal on stackable junk stays small.
	 */
	Map<String, Long> got;
	/** XP goals: last XP seen for the skill; gains between sightings are accumulated into n. */
	Long baseline;
	/**
	 * KC goals: per boss (lowercase), [0] the kill count baselined at first sighting after
	 * board import and [1] the latest reported count, so n = sum of (latest - baseline).
	 */
	Map<String, long[]> kc;

	Set<String> matchedSet()
	{
		if (matched == null)
		{
			matched = new HashSet<>();
		}
		return matched;
	}

	/**
	 * Records a distinct item/pet name, keeping the game's own capitalisation for display.
	 * Names are compared case-insensitively so a teammate can't make the same item count
	 * twice.
	 *
	 * @return whether the name was new
	 */
	boolean addName(String name)
	{
		Set<String> names = matchedSet();
		for (String candidate : names)
		{
			if (candidate.equalsIgnoreCase(name))
			{
				return false;
			}
		}
		names.add(name);
		return true;
	}

	/** Records a counted drop under its name (case-insensitive), most names capped. */
	void addGot(String name, long quantity)
	{
		if (name == null || name.isEmpty() || quantity <= 0)
		{
			return;
		}
		if (got == null)
		{
			got = new java.util.LinkedHashMap<>();
		}
		for (Map.Entry<String, Long> entry : got.entrySet())
		{
			if (entry.getKey().equalsIgnoreCase(name))
			{
				entry.setValue(entry.getValue() + quantity);
				return;
			}
		}
		if (got.size() < MAX_GOT_NAMES)
		{
			got.put(name, quantity);
		}
	}

	private static final int MAX_GOT_NAMES = 40;

	Map<String, long[]> kcMap()
	{
		if (kc == null)
		{
			kc = new HashMap<>();
		}
		return kc;
	}
}

package com.ironspubbingo;

/**
 * The kinds of automatically (or manually) trackable goals a bingo tile can contain.
 */
public enum GoalType
{
	/** Receive specific item drops, optionally restricted to certain sources. */
	DROP,
	/** Receive rare "purple" uniques from raids. */
	RAID_PURPLE,
	/** Gain kill count on bosses/activities that print kill count chat messages. */
	KC,
	/** Kill any NPC (including regular monsters): counts deaths of NPCs you damaged. */
	KILL,
	/** Receive pets (any pet, or specific ones via collection log messages). */
	PET,
	/** Gain a set amount of experience in a skill. */
	XP,
	/** Complete laps of a rooftop/agility course (detected like RuneLite's lap counter). */
	LAP,
	/** Receive a single drop/loot pile worth at least a set GE value. */
	VALUE,
	/** Match a game chat message against a regex (speed times, delve levels, quest completions, ...). */
	CHAT,
	/** Not automatically trackable; the player ticks the tile off by hand. */
	MANUAL,
}

