		}
		return teamStatusText();
	}

	/** Pinned tile indexes for this board, in pin order. Read from the config once per board. */
	List<Integer> pinnedTiles()
	{
		String key = boardKey;
		if (key == null)
		{
			return Collections.emptyList();
		}
		if (!key.equals(pinnedBoardKey))
		{
			List<Integer> loaded = new ArrayList<>();
			String saved = configManager.getConfiguration(IronsPubBingoConfig.GROUP, PINNED_PREFIX + key);
			for (String part : saved == null ? new String[0] : saved.split(","))
			{
				try
				{
					loaded.add(Integer.parseInt(part.trim()));
				}
				catch (NumberFormatException ignored)
				{
					// skip junk
				}
			}
			pinned = Collections.unmodifiableList(loaded);
			pinnedBoardKey = key;
		}
		return pinned;
	}

	boolean isTilePinned(int tileIndex)
	{
		return pinnedTiles().contains(tileIndex);
	}

	/** Pins or unpins a tile on the in-game overlay. Saved per board. */
	void togglePinnedTile(int tileIndex)
	{
		clientThread.invoke(() -> togglePinnedTileNow(tileIndex));
	}

	/** Clears every pin on this board. */
	void unpinAllTiles()
	{
		clientThread.invoke(() ->
		{
			String key = boardKey;
			if (key == null)
			{
				return;
			}
			pinned = Collections.emptyList();
			pinnedBoardKey = key;
			configManager.unsetConfiguration(IronsPubBingoConfig.GROUP, PINNED_PREFIX + key);
		});
	}

	private void togglePinnedTileNow(int tileIndex)
	{
		String key = boardKey;
		if (key == null)
		{
			return;
		}
		List<Integer> next = new ArrayList<>(pinnedTiles());
		if (!next.remove((Integer) tileIndex))
		{
			next.add(tileIndex);
		}
		pinned = Collections.unmodifiableList(next);
		pinnedBoardKey = key;
		if (next.isEmpty())
		{
			configManager.unsetConfiguration(IronsPubBingoConfig.GROUP, PINNED_PREFIX + key);
		}
		else
		{
			configManager.setConfiguration(IronsPubBingoConfig.GROUP, PINNED_PREFIX + key,
				next.stream().map(String::valueOf).collect(Collectors.joining(",")));
		}
	}

	/** Absolute start/end times for the countdown's tooltip, or null when none. */
	String eventWindowTooltip()
	{
		if (board == null || (board.startTime == null && board.endTime == null))
		{
			return null;
		}
		SimpleDateFormat format = new SimpleDateFormat("EEE d MMM yyyy, HH:mm");
		StringBuilder text = new StringBuilder("<html>");
		if (board.startTime != null)
		{
			text.append("Starts: ").append(format.format(new Date(board.startTime.toEpochMilli())));
		}
		if (board.endTime != null)
		{
			text.append(board.startTime != null ? "<br>" : "")
				.append("Ends: ").append(format.format(new Date(board.endTime.toEpochMilli())));
		}
		return text.append("</html>").toString();
	}

	/**
	 * Non-fatal notes about the loaded board, shown once after import so hosts catch
	 * mistakes (unresolvable icons, unlabelled chat patterns) before the event.
	 */
	List<String> lintBoard()
	{
		List<String> notes = new ArrayList<>();
		if (board == null)
		{
			return notes;
		}
		for (int i = 0; i < board.getTiles().size(); i++)
		{
			BingoTile tile = board.getTiles().get(i);
			if (tile.iconName != null)
			{
				iconFor(tile);
				if (tile.resolvedIconId <= 0)
				{
					notes.add("Tile " + (i + 1) + " \"" + tile.label + "\": icon \"" + tile.iconName
						+ "\" not found. Untradeable items need a numeric item ID");
				}
			}
			for (BingoGoal goal : tile.goals)
			{
				if (goal.goalType == GoalType.CHAT
					&& (goal.name == null || goal.name.trim().isEmpty())
					&& BingoGoal.readablePattern(goal.pattern) == null)
				{
					notes.add("Tile " + (i + 1) + " \"" + tile.label
						+ "\": chat pattern has no readable text. Set a progress bar label in the board");
				}
			}
		}
		return notes;
	}

	/**
	 * Warning when a teammate runs a newer revision of this board, or null. It sits right
	 * above the panel's Reimport from store button.
	 */
	String boardUpdateNotice()
	{
		if (newerBoardVersion == null)
		{
			return null;
		}
		// The store can flag an update the host pasted without bumping the version.
		String what = board != null && board.version != null && newerBoardVersion <= board.version
			? "The board changed" : "Board v" + newerBoardVersion + " is out";
		if (!newerBoardFromStore)
		{
			return what + ". Ask your host for the new board code.";
		}
		if (!teamStore.isConfigured())
		{
			return what + ". Ask your host for the new board code.";
		}
		return what + ". Press Reimport from store below.";
	}

	/** For Discord posts: says the post came from an outdated board, or null. */
	private String outdatedBoardNote()
	{
		Integer newer = newerBoardVersion;
		if (newer == null || board == null)
		{
			return null;
		}
		if (board.version == null)
		{
			return "Sent from an outdated board (v" + newer + " is out)";
		}
		return newer > board.version
			? "Sent from an outdated board (v" + board.version + ", v" + newer + " is out)"
			: "Sent from an outdated copy of this board";
	}

	/** Whether the newer-board notice came from the store, so a one-click reimport works. */
	boolean boardUpdateFromStore()
	{
		return newerBoardFromStore && newerBoardVersion != null;
	}

