package com.ironspubbingo;

import com.google.common.collect.ImmutableSet;
import java.util.Locale;
import java.util.Set;

/**
 * The three raids and their unique ("purple") drop tables, used to detect purples
 * from loot tracker events for the raid reward chests.
 */
public enum Raid
{
	COX("chambers of xeric", ImmutableSet.of(
		"twisted bow",
		"elder maul",
		"kodai insignia",
		"dragon claws",
		"ancestral hat",
		"ancestral robe top",
		"ancestral robe bottom",
		"dinh's bulwark",
		"dexterous prayer scroll",
		"arcane prayer scroll",
		"dragon hunter crossbow",
		"twisted buckler"
	)),
	TOB("theatre of blood", ImmutableSet.of(
		"scythe of vitur",
		"ghrazi rapier",
		"sanguinesti staff",
		"justiciar faceguard",
		"justiciar chestguard",
		"justiciar legguards",
		"avernic defender hilt"
	)),
	TOA("tombs of amascut", ImmutableSet.of(
		"tumeken's shadow",
		"elidinis' ward",
		"masori mask",
		"masori body",
		"masori chaps",
		"lightbearer",
		"osmumten's fang"
	));

	private final String lootSourcePrefix;
	private final Set<String> uniques;

	Raid(String lootSourcePrefix, Set<String> uniques)
	{
		this.lootSourcePrefix = lootSourcePrefix;
		this.uniques = uniques;
	}

	/**
	 * Maps a loot tracker event source name (e.g. "Chambers of Xeric: Challenge Mode")
	 * to the raid it belongs to, or null if the source is not a raid chest.
	 */
	static Raid fromLootSource(String source)
	{
		if (source == null)
		{
			return null;
		}
		String s = source.toLowerCase(Locale.ROOT);
		for (Raid raid : values())
		{
			if (s.startsWith(raid.lootSourcePrefix))
			{
				return raid;
			}
		}
		return null;
	}

	/**
	 * Whether the given item name is one of this raid's uniques. Matched by prefix so
	 * charge variants like "Scythe of vitur (uncharged)" also count.
	 */
	boolean isUnique(String itemName)
	{
		String name = itemName.toLowerCase(Locale.ROOT);
		for (String unique : uniques)
		{
			if (name.startsWith(unique))
			{
				return true;
			}
		}
		return false;
	}
}

package com.ironspubbingo;

import java.util.HashMap;
import java.util.Map;

/**
 * Everything known about one team member's progress: display name and their tile shares.
 * Keyed by the member's account hash in the team cache, party messages and the team store,
 * so display name changes don't split a member's contribution.
 */
class TeamMemberState
{
	String name;
	Map<Integer, TileProgress> tiles;

	Map<Integer, TileProgress> tilesMap()
	{
		if (tiles == null)
		{
			tiles = new HashMap<>();
		}
		return tiles;
	}

	/**
	 * Applies incoming tile shares last-write-wins by the owner's timestamp.
	 *
	 * @return whether anything changed
	 */
	boolean apply(String newName, Map<Integer, TileProgress> incoming, int maxTiles)
	{
		boolean changed = false;
		if (newName != null && !newName.isEmpty() && !newName.equals(name))
		{
			name = newName;
			changed = true;
		}
		if (incoming == null)
		{
			return changed;
		}
		for (Map.Entry<Integer, TileProgress> entry : incoming.entrySet())
		{
			Integer tile = entry.getKey();
			TileProgress share = entry.getValue();
			if (tile == null || share == null || tile < 0 || tile >= maxTiles)
			{
				continue;
			}
			TileProgress current = tilesMap().get(tile);
			if (current == null || ts(share) > ts(current))
			{
				tilesMap().put(tile, share);
				changed = true;
			}
		}
		return changed;
	}

	private static long ts(TileProgress p)
	{
		return p.ts == null ? 0 : p.ts;
	}
}

package com.ironspubbingo;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;

/**
 * Saved progress for one tile. Serialized to profile config keyed by the board hash,
 * so each account tracks its own progress per board.
 */
public class TileProgress
{
	List<GoalProgress> goals;
	/** Player ticked the tile off by hand (manual tiles, or host-approved overrides). */
	boolean manual;
	/**
	 * When the OWNER of this progress last changed it (epoch ms). Stamped only by the owning
	 * client, so relayed/stored copies can be compared last-write-wins without clock skew
	 * issues between players.
	 */
	Long ts;
	/**
	 * A copy safe to broadcast to teammates: counters, distinct item names, the manual
	 * flag and the owner timestamp, without per-member internals (XP/kill count baselines).
	 */
	TileProgress toShare(int goalCount)
	{
		TileProgress share = new TileProgress();
		share.manual = manual;
		share.ts = ts;
		for (int g = 0; g < goalCount; g++)
		{
			GoalProgress own = goal(g, goalCount);
			GoalProgress copy = share.goal(g, goalCount);
			copy.n = own.n;
			if (own.matched != null && !own.matched.isEmpty())
			{
				copy.matched = new HashSet<>(own.matched);
			}
			if (own.got != null && !own.got.isEmpty())
			{
				copy.got = new java.util.LinkedHashMap<>(own.got);
			}
		}
		return share;
	}

	/**
	 * Combines the progress of several team members into one team view:
	 * counters sum ("2 uniques" = one each from two people), distinct item sets union
	 * (the same champion scroll found twice still counts once), manual ticks OR.
	 */
	static TileProgress merge(int goalCount, Collection<TileProgress> members)
	{
		TileProgress merged = new TileProgress();
		for (TileProgress member : members)
		{
			merged.manual |= member.manual;
			for (int g = 0; g < goalCount; g++)
			{
				GoalProgress from = member.goal(g, goalCount);
				GoalProgress into = merged.goal(g, goalCount);
				into.n += from.n;
				if (from.matched != null)
				{
					for (String name : from.matched)
					{
						into.addName(name);
					}
				}
				if (from.got != null)
				{
					for (java.util.Map.Entry<String, Long> entry : from.got.entrySet())
					{
						into.addGot(entry.getKey(), entry.getValue() == null ? 0 : entry.getValue());
					}
				}
			}
		}
		return merged;
	}

	/**
	 * Returns the progress slot for a goal, growing the list to the tile's goal count
	 * so boards edited between sessions do not cause index errors.
	 */
	GoalProgress goal(int index, int goalCount)
	{
		if (goals == null)
		{
			goals = new ArrayList<>();
		}
		while (goals.size() < goalCount)
		{
			goals.add(new GoalProgress());
		}
		GoalProgress p = goals.get(index);
		if (p == null)
		{
			p = new GoalProgress();
			goals.set(index, p);
		}
		return p;
	}
}

package com.ironspubbingo;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

/**
 * Case-insensitive glob matching for item/NPC names in board files.
 * "*" matches any run of characters, so "Ancient page*" matches "Ancient page 1".
 */
final class Wildcards
{
	private Wildcards()
	{
	}

	static Pattern compile(String glob)
	{
		String[] parts = glob.split("\\*", -1);
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < parts.length; i++)
		{
			if (i > 0)
			{
				sb.append(".*");
			}
			if (!parts[i].isEmpty())
			{
				sb.append(Pattern.quote(parts[i]));
			}
		}
		return Pattern.compile(sb.toString(), Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE);
	}

	static List<Pattern> compileAll(List<String> globs)
	{
		List<Pattern> patterns = new ArrayList<>();
		if (globs != null)
		{
			for (String glob : globs)
			{
				if (glob != null && !glob.trim().isEmpty())
				{
					patterns.add(compile(glob.trim()));
				}
			}
		}
		return patterns;
	}

	/**
	 * True if any pattern fully matches the value. An empty pattern list matches everything,
	 * so omitting e.g. "sources" on a drop goal means "from anywhere".
	 */
	static boolean anyMatch(List<Pattern> patterns, String value)
	{
		if (patterns == null || patterns.isEmpty())
		{
			return true;
		}
		if (value == null)
		{
			return false;
		}
		for (Pattern p : patterns)
		{
			if (p.matcher(value).matches())
			{
				return true;
			}
		}
		return false;
	}
}

